killer-sudoku-helper.js
```
//
// This is only a SKELETON file for the 'Killer Sudoku Helper' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

/**
 * Returns all valid combinations of digits for a Killer Sudoku cage, sorted.
 * 
 * @param {Object} cage - The cage object.
 * @param {number} cage.size - Number of cells in the cage.
 * @param {number} cage.sum - The sum of the digits in the cage.
 * @param {number[]} [cage.excludedDigits] - Digits (1-9) that cannot be used in the cage (e.g. already present in row/col/box).
 * @returns {number[][]} - Array of valid combinations, each combination is a sorted array of digits.
 */
export const combinations = (cage) => {
  const size = cage.size;
  const sum = cage.sum;
  const excluded = cage.excludedDigits || [];

  // Digits available for use (1-9, minus excluded)
  const availableDigits = [];
  for (let d = 1; d <= 9; d++) {
    if (!excluded.includes(d)) {
      availableDigits.push(d);
    }
  }

  // Helper to generate all combinations of k elements from arr
  function kCombinations(arr, k) {
    if (k === 0) return [[]];
    if (arr.length < k) return [];
    const [first, ...rest] = arr;
    const withFirst = kCombinations(rest, k - 1).map(comb => [first, ...comb]);
    const withoutFirst = kCombinations(rest, k);
    return withFirst.concat(withoutFirst);
  }

  // Generate all size-length combinations of available digits
  const allCombs = kCombinations(availableDigits, size);

  // Filter to those whose sum matches
  const validCombs = allCombs.filter(comb => comb.reduce((a, b) => a + b, 0) === sum);

  // Sort each combination, then sort the list of combinations
  const sortedCombs = validCombs
    .map(comb => comb.slice().sort((a, b) => a - b))
    .sort((a, b) => {
      for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i]) return a[i] - b[i];
      }
      return 0;
    });

  return sortedCombs;
};
```

# USER
# Instructions

Implement the classic method for composing secret messages called a square code.

Given an English text, output the encoded version of that text.

First, the input is normalized: the spaces and punctuation are removed from the English text and the message is down-cased.

Then, the normalized characters are broken into rows.
These rows can be regarded as forming a rectangle when printed with intervening newlines.

For example, the sentence

```text
"If man was meant to stay on the ground, god would have given us roots."
```

is normalized to:

```text
"ifmanwasmeanttostayonthegroundgodwouldhavegivenusroots"
```

The plaintext should be organized into a rectangle as square as possible.
The size of the rectangle should be decided by the length of the message.

If `c` is the number of columns and `r` is the number of rows, then for the rectangle `r` x `c` find the smallest possible integer `c` such that:

- `r * c >= length of message`,
- and `c >= r`,
- and `c - r <= 1`.

Our normalized text is 54 characters long, dictating a rectangle with `c = 8` and `r = 7`:

```text
"ifmanwas"
"meanttos"
"tayonthe"
"groundgo"
"dwouldha"
"vegivenu"
"sroots  "
```

The coded message is obtained by reading down the columns going left to right.

The message above is coded as:

```text
"imtgdvsfearwermayoogoanouuiontnnlvtwttddesaohghnsseoau"
```

Output the encoded text in chunks that fill perfect rectangles `(r X c)`, with `c` chunks of `r` length, separated by spaces.
For phrases that are `n` characters short of the perfect rectangle, pad each of the last `n` chunks with a single trailing space.

```text
"imtgdvs fearwer mayoogo anouuio ntnnlvt wttddes aohghn  sseoau "
```

Notice that were we to stack these, we could visually decode the ciphertext back in to the original message:

```text
"imtgdvs"
"fearwer"
"mayoogo"
"anouuio"
"ntnnlvt"
"wttddes"
"aohghn "
"sseoau "
```

