#ifndef CIRCULAR_BUFFER_H
#define CIRCULAR_BUFFER_H

#include <vector>
#include <stdexcept>
#include <optional>
#include <cstddef>

namespace circular_buffer {

template <typename T>
class circular_buffer {
public:
    explicit circular_buffer(std::size_t capacity);

    void write(const T& value);
    void overwrite(const T& value);
    T read();
    void clear();

    bool is_empty() const;
    bool is_full() const;

private:
    std::vector<std::optional<T>> buffer_;
    std::size_t capacity_;
    std::size_t head_;
    std::size_t tail_;
    std::size_t size_;
};

template <typename T>
circular_buffer<T>::circular_buffer(std::size_t capacity)
    : buffer_(capacity), capacity_(capacity), head_(0), tail_(0), size_(0) {}

template <typename T>
void circular_buffer<T>::write(const T& value) {
    if (is_full()) {
        throw std::domain_error("Buffer is full");
    }
    buffer_[tail_] = value;
    tail_ = (tail_ + 1) % capacity_;
    ++size_;
}

template <typename T>
void circular_buffer<T>::overwrite(const T& value) {
    if (is_full()) {
        buffer_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        head_ = tail_;
    } else {
        buffer_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        ++size_;
    }
}

template <typename T>
T circular_buffer<T>::read() {
    if (is_empty()) {
        throw std::domain_error("Buffer is empty");
    }
    T value = *buffer_[head_];
    buffer_[head_].reset();
    head_ = (head_ + 1) % capacity_;
    --size_;
    return value;
}

template <typename T>
void circular_buffer<T>::clear() {
    for (auto& elem : buffer_) {
        elem.reset();
    }
    head_ = 0;
    tail_ = 0;
    size_ = 0;
}

template <typename T>
bool circular_buffer<T>::is_empty() const {
    return size_ == 0;
}

template <typename T>
bool circular_buffer<T>::is_full() const {
    return size_ == capacity_;
}

}  // namespace circular_buffer

#endif // CIRCULAR_BUFFER_H
```
