#include "phone_number.h"
#include <string>
#include <cctype>
#include <stdexcept>
#include <sstream>

namespace phone_number {

static std::string clean_number(const std::string& input) {
    std::string digits;
    for (char c : input) {
        if (std::isdigit(static_cast<unsigned char>(c))) {
            digits += c;
        }
    }

    // Remove country code if present
    if (digits.length() == 11 && digits[0] == '1') {
        digits = digits.substr(1);
    }

    // Validate length
    if (digits.length() != 10) {
        throw std::domain_error("Invalid number of digits");
    }

    // Area code and exchange code must start with 2-9
    if (digits[0] < '2' || digits[0] > '9') {
        throw std::domain_error("Area code must start with 2-9");
    }
    if (digits[3] < '2' || digits[3] > '9') {
        throw std::domain_error("Exchange code must start with 2-9");
    }

    return digits;
}

phone_number::phone_number(const std::string& input)
    : cleaned_number(clean_number(input))
{}

std::string phone_number::number() const {
    return cleaned_number;
}

std::string phone_number::area_code() const {
    return cleaned_number.substr(0, 3);
}

std::string phone_number::pretty() const {
    std::ostringstream oss;
    oss << "(" << cleaned_number.substr(0, 3) << ") "
        << cleaned_number.substr(3, 3) << "-"
        << cleaned_number.substr(6, 4);
    return oss.str();
}

}  // namespace phone_number
