// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// findPath finds the path from the current node to the node with the given value.
// It returns the path as a slice of *Tree, or nil if not found.
func (tr *Tree) findPath(value string) []*Tree {
	if tr == nil {
		return nil
	}
	if tr.value == value {
		return []*Tree{tr}
	}
	for _, child := range tr.children {
		if path := child.findPath(value); path != nil {
			return append([]*Tree{tr}, path...)
		}
	}
	return nil
}

// FromPov returns the pov from the node specified in the argument.
func (tr *Tree) FromPov(from string) *Tree {
	path := tr.findPath(from)
	if path == nil {
		return nil
	}
	// path: [root, ..., from]
	// We want to re-root the tree at "from"
	return reroot(path)
}

// reroot reconstructs the tree so that the last node in path is the new root.
// path is [root, ..., newRoot]
func reroot(path []*Tree) *Tree {
	n := len(path)
	if n == 0 {
		return nil
	}
	// Start from the new root
	newRoot := &Tree{
		value:    path[n-1].value,
		children: make([]*Tree, 0),
	}
	curr := newRoot
	// Traverse path backwards, adding siblings and parent as children
	for i := n - 2; i >= 0; i-- {
		parent := path[i]
		child := path[i+1]
		// Add all siblings of child (i.e., parent's children except child) as children of curr
		for _, sibling := range parent.children {
			if sibling != child {
				curr.children = append(curr.children, cloneSubtree(sibling))
			}
		}
		// Now, make a new node for the parent, with no children yet
		parentNode := &Tree{
			value:    parent.value,
			children: make([]*Tree, 0),
		}
		curr.children = append(curr.children, parentNode)
		curr = parentNode
	}
	return newRoot
}

// cloneSubtree clones the entire subtree rooted at tr.
func cloneSubtree(tr *Tree) *Tree {
	if tr == nil {
		return nil
	}
	newChildren := make([]*Tree, len(tr.children))
	for i, child := range tr.children {
		newChildren[i] = cloneSubtree(child)
	}
	return &Tree{
		value:    tr.value,
		children: newChildren,
	}
}

// findPathValues finds the path from the current node to the node with the given value.
// It returns the path as a slice of strings, or nil if not found.
func (tr *Tree) findPathValues(value string) []string {
	if tr == nil {
		return nil
	}
	if tr.value == value {
		return []string{tr.value}
	}
	for _, child := range tr.children {
		if path := child.findPathValues(value); path != nil {
			return append([]string{tr.value}, path...)
		}
	}
	return nil
}

// PathTo returns the shortest path between two nodes in the tree.
func (tr *Tree) PathTo(from, to string) []string {
	// Re-root the tree at "from"
	newRoot := tr.FromPov(from)
	if newRoot == nil {
		return nil
	}
	return newRoot.findPathValues(to)
}
