#include "allergies.h"
#include <unordered_map>

namespace allergies {

const std::vector<std::string> allergy_test::allergen_list = {
    "eggs",
    "peanuts",
    "shellfish",
    "strawberries",
    "tomatoes",
    "chocolate",
    "pollen",
    "cats"
};

const std::unordered_map<std::string, unsigned int> allergy_test::allergen_scores = {
    {"eggs", 1},
    {"peanuts", 2},
    {"shellfish", 4},
    {"strawberries", 8},
    {"tomatoes", 16},
    {"chocolate", 32},
    {"pollen", 64},
    {"cats", 128}
};

allergy_test::allergy_test(unsigned int score)
    : score_(score)
{}

bool allergy_test::is_allergic_to(const std::string& allergen) const {
    auto it = allergen_scores.find(allergen);
    if (it == allergen_scores.end()) {
        return false;
    }
    return (score_ & it->second) != 0;
}

std::vector<std::string> allergy_test::get_allergies() const {
    std::vector<std::string> result;
    for (const auto& allergen : allergen_list) {
        if (is_allergic_to(allergen)) {
            result.push_back(allergen);
        }
    }
    return result;
}

}  // namespace allergies
