const NONE = 'NONE';
const BLACK = 'BLACK';
const WHITE = 'WHITE';

function getOwner(owners) {
  if (owners.size === 1) {
    const owner = owners.values().next().value;
    if (owner === 'B') return BLACK;
    if (owner === 'W') return WHITE;
  }
  return NONE;
}

function inBounds(board, x, y) {
  return y >= 0 && y < board.length && x >= 0 && x < board[0].length;
}

function getNeighbors(x, y, board) {
  const deltas = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
  ];
  const neighbors = [];
  for (const [dx, dy] of deltas) {
    const nx = x + dx;
    const ny = y + dy;
    if (inBounds(board, nx, ny)) {
      neighbors.push([nx, ny]);
    }
  }
  return neighbors;
}

function floodFill(board, x, y, visited) {
  const queue = [[x, y]];
  const territory = [];
  const owners = new Set();
  while (queue.length > 0) {
    const [cx, cy] = queue.pop();
    if (visited[cy][cx]) continue;
    visited[cy][cx] = true;
    territory.push([cy, cx]);
    for (const [nx, ny] of getNeighbors(cx, cy, board)) {
      const cell = board[ny][nx];
      if (cell === ' ') {
        if (!visited[ny][nx]) {
          queue.push([nx, ny]);
        }
      } else if (cell === 'B' || cell === 'W') {
        owners.add(cell);
      }
    }
  }
  return {
    owner: getOwner(owners),
    territory,
  };
}

export class GoCounting {
  constructor(board) {
    // Convert board to 2D array of chars for easier access
    this.board = board.map(row => row.split(''));
    this.height = this.board.length;
    this.width = this.board[0]?.length || 0;
  }

  getTerritory(x, y) {
    if (!inBounds(this.board, x, y)) {
      throw new Error('Invalid coordinate');
    }
    if (this.board[y][x] !== ' ') {
      return {
        owner: NONE,
        territory: [],
      };
    }
    // Prepare visited array
    const visited = Array.from({ length: this.height }, () =>
      Array(this.width).fill(false)
    );
    return floodFill(this.board, x, y, visited);
  }

  getTerritories() {
    const visited = Array.from({ length: this.height }, () =>
      Array(this.width).fill(false)
    );
    const territoryBlack = [];
    const territoryWhite = [];
    const territoryNone = [];
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (this.board[y][x] === ' ' && !visited[y][x]) {
          const { owner, territory } = floodFill(this.board, x, y, visited);
          if (owner === BLACK) {
            territoryBlack.push(...territory);
          } else if (owner === WHITE) {
            territoryWhite.push(...territory);
          } else {
            territoryNone.push(...territory);
          }
        }
      }
    }
    return {
      territoryBlack,
      territoryWhite,
      territoryNone,
    };
  }
}
