package variablelengthquantity

import (
	"errors"
)

// EncodeVarint encodes a slice of uint32s into VLQ bytes.
func EncodeVarint(input []uint32) []byte {
	var result []byte
	for _, n := range input {
		if n == 0 {
			result = append(result, 0x00)
			continue
		}
		var bytes []byte
		for n > 0 {
			b := byte(n & 0x7F)
			bytes = append([]byte{b}, bytes...)
			n >>= 7
		}
		for i := 0; i < len(bytes)-1; i++ {
			bytes[i] |= 0x80 // set continuation bit
		}
		result = append(result, bytes...)
	}
	return result
}

// DecodeVarint decodes a slice of VLQ bytes into uint32s.
func DecodeVarint(input []byte) ([]uint32, error) {
	var result []uint32
	var value uint32
	var bytesRead int

	for i, b := range input {
		value = (value << 7) | uint32(b&0x7F)
		bytesRead++
		if b&0x80 == 0 {
			result = append(result, value)
			value = 0
			bytesRead = 0
		} else if bytesRead > 5 {
			// 5*7=35 bits, but uint32 is 32 bits, so more than 5 bytes is invalid
			return nil, errors.New("VLQ sequence is too long for uint32")
		}
	}

	if bytesRead != 0 {
		return nil, errors.New("incomplete VLQ sequence")
	}

	return result, nil
}
