//
// This is only a SKELETON file for the 'Meetup' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const WEEKDAYS = {
  Sunday: 0,
  Monday: 1,
  Tuesday: 2,
  Wednesday: 3,
  Thursday: 4,
  Friday: 5,
  Saturday: 6,
};

const TEENTH_DAYS = [13, 14, 15, 16, 17, 18, 19];

export const meetup = (year, month, weekday, which) => {
  // month is 1-based, JS Date expects 0-based
  const weekdayNum = WEEKDAYS[weekday];
  const jsMonth = month - 1;

  let day;

  if (which === 'teenth') {
    for (let d of TEENTH_DAYS) {
      const date = new Date(year, jsMonth, d);
      if (date.getDay() === weekdayNum) {
        day = d;
        break;
      }
    }
  } else if (['first', 'second', 'third', 'fourth'].includes(which)) {
    // Find the first occurrence of the weekday in the month
    let firstDay = new Date(year, jsMonth, 1);
    let firstWeekday = firstDay.getDay();
    // Offset to the first desired weekday
    let offset = (weekdayNum - firstWeekday + 7) % 7;
    // Add 0, 7, 14, 21 for first, second, third, fourth
    const weekOffset = {
      first: 0,
      second: 1,
      third: 2,
      fourth: 3,
    };
    day = 1 + offset + 7 * weekOffset[which];
  } else if (which === 'last') {
    // Find the last day of the month
    let lastDay = new Date(year, jsMonth + 1, 0).getDate();
    for (let d = lastDay; d >= lastDay - 6; d--) {
      const date = new Date(year, jsMonth, d);
      if (date.getDay() === weekdayNum) {
        day = d;
        break;
      }
    }
  } else {
    throw new Error('Unknown "which" value');
  }

  return new Date(year, jsMonth, day);
};
