	{0, -1},  // left
	{1, 0},   // down
	{-1, 0},  // up
	{1, 1},   // down-right
	{-1, -1}, // up-left
	{1, -1},  // down-left
	{-1, 1},  // up-right
}

func Solve(words []string, puzzle []string) (map[string][2][2]int, error) {
