type Point [2]int

// directions: [rowDelta, colDelta]
var directions = []Point{
	{0, 1},   // right
	{0, -1},  // left
	{1, 0},   // down
	{-1, 0},  // up
	{1, 1},   // down-right
	{-1, -1}, // up-left
	{1, -1},  // down-left
	{-1, 1},  // up-right
}

func Solve(words []string, puzzle []string) (map[string][2][2]int, error) {
	if len(puzzle) == 0 {
		return nil, errors.New("puzzle is empty")
	}
	nRows := len(puzzle)
	nCols := len(puzzle[0])
	for _, row := range puzzle {
		if len(row) != nCols {
			return nil, errors.New("puzzle is not a rectangle")
		}
	}

	grid := make([][]rune, nRows)
	for i := range puzzle {
		grid[i] = []rune(puzzle[i])
	}

	result := make(map[string][2][2]int)
	for _, word := range words {
		found := false
		wordRunes := []rune(word)
		for r := 0; r < nRows && !found; r++ {
			for c := 0; c < nCols && !found; c++ {
				for _, dir := range directions {
					if matchWord(grid, r, c, dir, wordRunes) {
						endR := r + dir[0]*(len(wordRunes)-1)
						endC := c + dir[1]*(len(wordRunes)-1)
						result[word] = [2][2]int{{r, c}, {endR, endC}}
						found = true
						break
					}
				}
			}
		}
		if !found {
			return nil, errors.New("word not found: " + word)
		}
	}
	return result, nil
}

func matchWord(grid [][]rune, r, c int, dir Point, word []rune) bool {
	nRows := len(grid)
	nCols := len(grid[0])
	for i := 0; i < len(word); i++ {
		nr := r + dir[0]*i
		nc := c + dir[1]*i
		if nr < 0 || nr >= nRows || nc < 0 || nc >= nCols {
			return false
		}
