		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse number must be between 0 and 99")
	}

	var verse string
	switch n {
	case 0:
		verse = fmt.Sprintf("%s, %s.\nGo to the store and buy some more, %s.\n",
			capitalize(bottleWallPhrase(0)),
			bottlePhrase(0),
			bottleWallPhrase(99),
		)
	case 1:
		verse = fmt.Sprintf("%s, %s.\nTake it down and pass it around, %s.\n",
			capitalize(bottleWallPhrase(1)),
			bottlePhrase(1),
			bottleWallPhrase(0),
		)
	case 2:
		verse = fmt.Sprintf("%s, %s.\nTake one down and pass it around, %s.\n",
			capitalize(bottleWallPhrase(2)),
			bottlePhrase(2),
			bottleWallPhrase(1),
		)
	default:
		verse = fmt.Sprintf("%s, %s.\nTake one down and pass it around, %s.\n",
			capitalize(bottleWallPhrase(n)),
			bottlePhrase(n),
			bottleWallPhrase(n-1),
		)
	}
	return verse, nil
}

func Verses(start, stop int) (string, error) {
	if start < stop || start > 99 || stop < 0 {
		return "", errors.New("invalid range")
	}
	var verses []string
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		verses = append(verses, v)
	}
	return strings.Join(verses, "\n"), nil
}

func Song() string {
	song, _ := Verses(99, 0)
	return song
}
