class TwoBucket {
    private final int bucketOneCap;
    private final int bucketTwoCap;
    private final int desiredLiters;
    private final String startBucket;

    private int totalMoves;
    private String finalBucket;
    private int otherBucket;

    public TwoBucket(int bucketOneCap, int bucketTwoCap, int desiredLiters, String startBucket) {
        this.bucketOneCap = bucketOneCap;
        this.bucketTwoCap = bucketTwoCap;
        this.desiredLiters = desiredLiters;
        this.startBucket = startBucket;

        solve();
    }

    private void solve() {
        // Try both strategies: start with bucket one or bucket two
        if (startBucket.equals("one")) {
            simulate(bucketOneCap, bucketTwoCap, desiredLiters, true);
        } else {
            simulate(bucketTwoCap, bucketOneCap, desiredLiters, false);
        }
    }

    // Simulate the process, always filling the start bucket first
    private void simulate(int startCap, int otherCap, int goal, boolean startIsOne) {
        int start = 0;
        int other = 0;
        int moves = 0;

        // To avoid infinite loops, keep track of visited states
        java.util.Set<String> seen = new java.util.HashSet<>();

        while (true) {
            // Check for goal
            if (start == goal) {
                this.totalMoves = moves;
                this.finalBucket = startIsOne ? "one" : "two";
                this.otherBucket = other;
                return;
            }
            if (other == goal) {
                this.totalMoves = moves;
                this.finalBucket = startIsOne ? "two" : "one";
                this.otherBucket = start;
                return;
            }

            String state = start + "," + other;
            if (seen.contains(state)) {
                // No solution
                break;
            }
            seen.add(state);

            // If start bucket is empty, fill it
            if (start == 0) {
                start = startCap;
                moves++;
            }
            // If other bucket is full, empty it
            else if (other == otherCap) {
                other = 0;
                moves++;
            }
            // Pour from start to other
            else {
                int pour = Math.min(start, otherCap - other);
                start -= pour;
                other += pour;
                moves++;
            }

            // Rule: may not arrive at a state where the initial starting bucket is empty and the other bucket is full
            if (start == 0 && other == otherCap) {
                break;
            }
        }

        // If we reach here, no solution found
        throw new IllegalArgumentException("No solution possible with the given parameters.");
    }

    int getTotalMoves() {
        return totalMoves;
    }

    String getFinalBucket() {
        return finalBucket;
    }

    int getOtherBucket() {
        return otherBucket;
    }
}
