//
// This is only a SKELETON file for the 'Wordy' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const OPERATIONS = {
  'plus': (a, b) => a + b,
  'minus': (a, b) => a - b,
  'multiplied by': (a, b) => a * b,
  'divided by': (a, b) => {
    if (b === 0) throw new Error('Division by zero');
    return Math.trunc(a / b);
  },
};

function parseQuestion(question) {
  if (typeof question !== 'string') throw new Error('Invalid question');
  if (!question.startsWith('What is ') || !question.endsWith('?')) {
    throw new Error('Unknown operation');
  }

  // Remove "What is " at the start and "?" at the end
  let content = question.slice(8, -1).trim();

  // Special case: just a number
  if (/^-?\d+$/.test(content)) {
    return [parseInt(content, 10)];
  }

  // Tokenize: match numbers (including negative), and operation words
  // Supported operations: plus, minus, multiplied by, divided by
  // We'll use a regex to match numbers and operation phrases
  const tokens = [];
  let regex = /(-?\d+)|(plus|minus|multiplied by|divided by)/g;
  let match;
  let lastIndex = 0;

  while ((match = regex.exec(content)) !== null) {
    if (match.index !== lastIndex) {
      // There is an unsupported or invalid token in between
      throw new Error('Unknown operation');
    }
    if (match[1]) {
      tokens.push(parseInt(match[1], 10));
    } else if (match[2]) {
      tokens.push(match[2]);
    }
    lastIndex = regex.lastIndex;
  }

  // If we didn't consume the whole string, it's invalid
  if (lastIndex !== content.length) {
    throw new Error('Unknown operation');
  }

  // Validate token sequence: must alternate number, op, number, op, number, ...
  if (tokens.length < 1 || typeof tokens[0] !== 'number') {
    throw new Error('Syntax error');
  }
  for (let i = 1; i < tokens.length; i += 2) {
    if (typeof tokens[i] !== 'string' || !(tokens[i] in OPERATIONS)) {
      throw new Error('Unknown operation');
    }
    if (typeof tokens[i + 1] !== 'number') {
      throw new Error('Syntax error');
    }
  }

  return tokens;
}

export const answer = (question) => {
  let tokens;
  try {
    tokens = parseQuestion(question);
  } catch (e) {
    if (e.message === 'Unknown operation' || e.message === 'Syntax error') {
      throw new Error('Unknown operation');
    }
    throw e;
  }

  // If only a single number, return it
  if (tokens.length === 1 && typeof tokens[0] === 'number') {
    return tokens[0];
  }

  // Evaluate left-to-right
  let result = tokens[0];
  for (let i = 1; i < tokens.length; i += 2) {
    const op = tokens[i];
    const num = tokens[i + 1];
    result = OPERATIONS[op](result, num);
  }
  return result;
};
