//
// This is only a SKELETON file for the 'Grade School' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class GradeSchool {
  constructor() {
    // Map grade (number) -> array of student names
    this._grades = {};
    // Set of all student names to prevent duplicates
    this._students = new Set();
  }

  roster() {
    // Return a deep copy of the roster, sorted as required
    const result = {};
    Object.keys(this._grades)
      .map(Number)
      .sort((a, b) => a - b)
      .forEach(grade => {
        result[grade] = [...this._grades[grade]].sort();
      });
    return result;
  }

  add(name, grade) {
    // Prevent adding the same student more than once
    if (this._students.has(name)) {
      throw new Error('Student is already in the roster');
    }
    if (!this._grades[grade]) {
      this._grades[grade] = [];
    }
    this._grades[grade].push(name);
    this._students.add(name);
  }

  grade(grade) {
    // Return a sorted copy of the students in the given grade
    if (!this._grades[grade]) {
      return [];
    }
    return [...this._grades[grade]].sort();
  }
}
