        if (player == 'O') {
            // O: top to bottom
            for (int col = 0; col < cols; col++) {
                if (board[0][col] == 'O' && dfsO(0, col, visited)) {
                    return true;
                }
            }
        } else if (player == 'X') {
            // X: left to right
            for (int row = 0; row < rows; row++) {
                if (board[row][0] == 'X' && dfsX(row, 0, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    // DFS for O (top to bottom)
    private boolean dfsO(int row, int col, boolean[][] visited) {
        if (row == rows - 1) {
            return true;
        }
        visited[row][col] = true;
        int[][] directions = {
            {-1, 0}, {-1, 1}, {0, -1},
            {0, 1}, {1, -1}, {1, 0}
        };
        for (int[] d : directions) {
            int nr = row + d[0];
            int nc = col + d[1];
            if (inBounds(nr, nc) && !visited[nr][nc] && board[nr][nc] == 'O') {
                if (dfsO(nr, nc, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    // DFS for X (left to right)
    private boolean dfsX(int row, int col, boolean[][] visited) {
        if (col == cols - 1) {
            return true;
        }
        visited[row][col] = true;
        int[][] directions = {
            {-1, 0}, {-1, 1}, {0, -1},
            {0, 1}, {1, -1}, {1, 0}
        };
        for (int[] d : directions) {
            int nr = row + d[0];
            int nc = col + d[1];
            if (inBounds(nr, nc) && !visited[nr][nc] && board[nr][nc] == 'X') {
                if (dfsX(nr, nc, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean inBounds(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
