class Connect {

    private final char[][] board;
    private final int rows;
    private final int cols;

    public enum Winner {
        NONE,
        PLAYER_O,
        PLAYER_X
    }

    public Connect(String[] board) {
        this.rows = board.length;
        this.cols = board.length == 0 ? 0 : board[0].replaceAll("\\s+", "").length();
        this.board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = board[i].replaceAll("\\s+", "");
            for (int j = 0; j < cols; j++) {
                this.board[i][j] = line.charAt(j);
            }
        }
    }

    public Winner computeWinner() {
        if (hasPath('O')) {
            return Winner.PLAYER_O;
        }
        if (hasPath('X')) {
            return Winner.PLAYER_X;
        }
        return Winner.NONE;
    }

    private boolean hasPath(char player) {
        boolean[][] visited = new boolean[rows][cols];
        if (player == 'O') {
            // O: top to bottom
            for (int col = 0; col < cols; col++) {
                if (board.length > 0 && board[0][col] == 'O' && dfsO(0, col, visited)) {
