package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// localeConfig holds locale-specific formatting details
type localeConfig struct {
	headerDate        string
	headerDescription string
	headerChange      string
	dateFormat        string // Go time format string
	descWidth         int
	dateWidth         int
	changeWidth       int
	currencyFmt       func(currency string, amount int) (string, error)
}

var localeConfigs = map[string]localeConfig{
	"en-US": {
		headerDate:        "Date",
		headerDescription: "Description",
		headerChange:      "Change",
		dateFormat:        "01/02/2006",
		descWidth:         25,
		dateWidth:         10,
		changeWidth:       13,
		currencyFmt:       formatCurrencyEN,
	},
	"nl-NL": {
		headerDate:        "Datum",
		headerDescription: "Omschrijving",
		headerChange:      "Verandering",
		dateFormat:        "02-01-2006",
		descWidth:         25,
		dateWidth:         10,
		changeWidth:       13,
		currencyFmt:       formatCurrencyNL,
	},
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	cfg, ok := localeConfigs[locale]
	if !ok {
		return "", errors.New("unsupported locale")
	}

	// Check for valid currency
	if _, err := currencySymbol(currency); err != nil {
		return "", err
	}

	// Defensive copy
	entriesCopy := make([]Entry, len(entries))
	copy(entriesCopy, entries)

	// Sort entries
	sort.SliceStable(entriesCopy, func(i, j int) bool {
		// Parse dates
		ti, erri := time.Parse("2006-01-02", entriesCopy[i].Date)
		tj, errj := time.Parse("2006-01-02", entriesCopy[j].Date)
		if erri != nil || errj != nil {
			// Fallback to string compare if date invalid
			if entriesCopy[i].Date != entriesCopy[j].Date {
				return entriesCopy[i].Date < entriesCopy[j].Date
			}
		} else if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		// Then by description
		if entriesCopy[i].Description != entriesCopy[j].Description {
			return entriesCopy[i].Description < entriesCopy[j].Description
		}
		// Then by change
		return entriesCopy[i].Change < entriesCopy[j].Change
	})

	// Header
	header := fmt.Sprintf("%-*s | %-*s | %s\n",
		cfg.dateWidth, cfg.headerDate,
		cfg.descWidth, cfg.headerDescription,
		cfg.headerChange,
	)

	var sb strings.Builder
	sb.WriteString(header)

	for _, entry := range entriesCopy {
		// Parse and format date
		dateStr, err := formatDate(entry.Date, cfg.dateFormat)
		if err != nil {
			return "", err
		}

		// Format description
		desc := formatDescription(entry.Description, cfg.descWidth)

		// Format change
		changeStr, err := cfg.currencyFmt(currency, entry.Change)
		if err != nil {
			return "", err
		}

		// Pad change to the right width
		// Use right-justified padding, but for negative values in en-US, add an extra space to match test
		// The test expects 6 spaces before (€10.00), not 3, so pad to width, not just to length
		changeStr = padLeft(changeStr, cfg.changeWidth)

		// Compose line
		line := fmt.Sprintf("%-*s | %-*s | %s\n",
			cfg.dateWidth, dateStr,
			cfg.descWidth, desc,
			changeStr,
		)
		sb.WriteString(line)
	}

	return sb.String(), nil
}

func formatDate(dateStr, format string) (string, error) {
	t, err := time.Parse("2006-01-02", dateStr)
	if err != nil {
		return "", errors.New("invalid date format")
	}
	return t.Format(format), nil
}

func formatDescription(desc string, width int) string {
	if len(desc) > width {
		if width > 3 {
			return desc[:width-3] + "..."
		}
		return desc[:width]
	}
	return desc + strings.Repeat(" ", width-len(desc))
}

func padLeft(s string, width int) string {
	// Use rune-aware padding
	runeLen := len([]rune(s))
	if runeLen >= width {
		return s
	}
	return strings.Repeat(" ", width-runeLen) + s
}

func formatCurrencyEN(currency string, amount int) (string, error) {
	negative := amount < 0
	if negative {
		amount = -amount
	}
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	major := amount / 100
	minor := amount % 100

	// Format with thousands separator
	majorStr := formatThousands(major, ",")
	val := fmt.Sprintf("%s%s.%02d", symbol, majorStr, minor)
	if negative {
		val = "(" + val + ")"
	} else {
		val += " "
	}
	return val, nil
}

func formatCurrencyNL(currency string, amount int) (string, error) {
	negative := amount < 0
	if negative {
		amount = -amount
	}
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	major := amount / 100
	minor := amount % 100

	// Format with thousands separator (dot)
	majorStr := formatThousands(major, ".")
	val := fmt.Sprintf("%s %s,%02d", symbol, majorStr, minor)
	if negative {
		val += "-"
	} else {
		val += " "
	}
	return val, nil
}

func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	default:
		return "", errors.New("unsupported currency")
	}
}

func formatThousands(n int, sep string) string {
	s := strconv.Itoa(n)
	if len(s) <= 3 {
		return s
	}
	var out []byte
	pre := len(s) % 3
	if pre > 0 {
		out = append(out, s[:pre]...)
		if len(s) > pre {
			out = append(out, sep...)
		}
	}
	for i := pre; i < len(s); i += 3 {
		out = append(out, s[i:i+3]...)
		if i+3 < len(s) {
			out = append(out, sep...)
		}
	}
	return string(out)
}
