import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

public class Ledger {

    // Change log:
    // 1. Extracted formatting logic into helper methods for clarity and reuse.
    // 2. Introduced a LedgerFormat class to encapsulate locale/currency-specific formatting.
    // 3. Simplified sorting and entry grouping logic.
    // 4. Improved variable naming and removed unnecessary null initializations.
    // 5. Used Arrays.asList and streams for sorting.
    // 6. Moved description truncation and amount formatting to helper methods.
    // 7. Kept all public APIs and class names unchanged.

    public LedgerEntry createLedgerEntry(String d, String desc, int c) {
        LedgerEntry le = new LedgerEntry();
        le.setChange(c);
        le.setDescription(desc);
        le.setLocalDate(LocalDate.parse(d));
        return le;
    }

    public String format(String currency, String locale, LedgerEntry[] entries) {
        LedgerFormat fmt = LedgerFormat.forCurrencyAndLocale(currency, locale);

        StringBuilder sb = new StringBuilder();
        sb.append(fmt.header);

        if (entries.length == 0) {
            return sb.toString();
        }

        // Sort entries: negative first, then positive, both by date ascending
        List<LedgerEntry> entryList = new ArrayList<>(Arrays.asList(entries));
        entryList.sort(new LedgerEntryComparator());

        for (LedgerEntry entry : entryList) {
            String date = entry.getLocalDate().format(fmt.dateFormatter);
            String desc = truncateDescription(entry.getDescription());
            String amount = fmt.formatAmount(entry.getChange());

            sb.append("\n");
            sb.append(String.format("%s | %-25s | %13s", date, desc, amount));
        }

        return sb.toString();
    }

    private String truncateDescription(String desc) {
        if (desc.length() > 25) {
            return desc.substring(0, 22) + "...";
        }
        return desc;
    }

    // Helper class for formatting based on currency and locale
    private static class LedgerFormat {
        final String header;
        final String currencySymbol;
        final DateTimeFormatter dateFormatter;
        final String decimalSeparator;
        final String thousandsSeparator;
        final boolean symbolFirst;
        final boolean negativeParens; // en-US negative in parens, nl-NL negative with minus
        final boolean spaceBetweenSymbolAndAmount;
        final boolean spaceAroundAmount;

        private LedgerFormat(String header, String currencySymbol, String datePattern,
                             String decimalSeparator, String thousandsSeparator,
                             boolean symbolFirst, boolean negativeParens,
                             boolean spaceBetweenSymbolAndAmount, boolean spaceAroundAmount) {
            this.header = header;
            this.currencySymbol = currencySymbol;
            this.dateFormatter = DateTimeFormatter.ofPattern(datePattern);
            this.decimalSeparator = decimalSeparator;
            this.thousandsSeparator = thousandsSeparator;
            this.symbolFirst = symbolFirst;
            this.negativeParens = negativeParens;
            this.spaceBetweenSymbolAndAmount = spaceBetweenSymbolAndAmount;
            this.spaceAroundAmount = spaceAroundAmount;
        }

        static LedgerFormat forCurrencyAndLocale(String currency, String locale) {
            if (!currency.equals("USD") && !currency.equals("EUR")) {
                throw new IllegalArgumentException("Invalid currency");
            }
            if (!locale.equals("en-US") && !locale.equals("nl-NL")) {
                throw new IllegalArgumentException("Invalid locale");
            }

            if (currency.equals("USD")) {
                if (locale.equals("en-US")) {
                    return new LedgerFormat(
                            "Date       | Description               | Change       ",
                            "$", "MM/dd/yyyy", ".", ",",
                            true, true, false, false
                    );
                } else { // nl-NL
                    return new LedgerFormat(
                            "Datum      | Omschrijving              | Verandering  ",
                            "$", "dd/MM/yyyy", ",", ".",
                            true, false, true, true
                    );
                }
            } else { // EUR
                if (locale.equals("en-US")) {
                    return new LedgerFormat(
                            "Date       | Description               | Change       ",
                            "€", "MM/dd/yyyy", ".", ",",
                            true, true, false, false
                    );
                } else { // nl-NL
                    return new LedgerFormat(
                            "Datum      | Omschrijving              | Verandering  ",
                            "€", "dd/MM/yyyy", ",", ".",
                            true, false, true, true
                    );
                }
            }
        }

        String formatAmount(double change) {
            boolean negative = change < 0;
            double absValue = Math.abs(change) / 100.0;

            // Format number with thousands and decimal separators
            String[] parts = String.format(Locale.US, "%.2f", absValue).split("\\.");
            String intPart = parts[0];
            String fracPart = parts[1];

            String intWithSep = "";
            int count = 0;
            for (int i = intPart.length() - 1; i >= 0; i--) {
                intWithSep = intPart.charAt(i) + intWithSep;
                count++;
                if (count % 3 == 0 && i != 0) {
                    intWithSep = thousandsSeparator + intWithSep;
                }
            }

            String amount = intWithSep + decimalSeparator + fracPart;

            // Compose with currency symbol
            String result;
            if (symbolFirst) {
                if (spaceBetweenSymbolAndAmount) {
                    result = currencySymbol + " " + amount;
                } else {
                    result = currencySymbol + amount;
                }
            } else {
                if (spaceBetweenSymbolAndAmount) {
                    result = amount + " " + currencySymbol;
                } else {
                    result = amount + currencySymbol;
                }
            }

            // Negative formatting
            if (negative) {
                if (negativeParens) {
                    result = "(" + result + ")";
                } else {
                    // nl-NL: symbol, space, minus, amount, space
                    result = currencySymbol + " -" + result.replace(currencySymbol, "").trim() + " ";
                }
            } else if (spaceAroundAmount) {
                result = " " + result + " ";
            } else {
                result = result + " ";
            }

            return result;
        }
    }

    // Sort: negative first by date, then positive by date
    private static class LedgerEntryComparator implements Comparator<LedgerEntry> {
        @Override
        public int compare(LedgerEntry a, LedgerEntry b) {
            if ((a.getChange() < 0 && b.getChange() >= 0)) {
                return -1;
            }
            if ((a.getChange() >= 0 && b.getChange() < 0)) {
                return 1;
            }
            return a.getLocalDate().compareTo(b.getLocalDate());
        }
    }

    public static class LedgerEntry {
        LocalDate localDate;
        String description;
        double change;

        public LocalDate getLocalDate() {
            return localDate;
        }

        public void setLocalDate(LocalDate localDate) {
            this.localDate = localDate;
