//
// This is only a SKELETON file for the 'Forth' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

function isNumber(token) {
  // Accepts negative numbers as well
  return /^-?\d+$/.test(token);
}

function toNumber(token) {
  return parseInt(token, 10);
}

function normalizeWord(word) {
  return word.toLowerCase();
}

export class Forth {
  constructor() {
    this._stack = [];
    this._words = {};
  }

  evaluate(input) {
    // Tokenize input, handling word definitions
    let tokens = this._tokenize(input);

    let i = 0;
    while (i < tokens.length) {
      let token = tokens[i];

      if (isNumber(token)) {
        this._stack.push(toNumber(token));
        i++;
        continue;
      }

      let word = normalizeWord(token);

      // Arithmetic
      if (word === '+') {
        this._requireStack(2, 'Addition');
        let b = this._stack.pop();
        let a = this._stack.pop();
        this._stack.push(a + b);
        i++;
        continue;
      }
      if (word === '-') {
        this._requireStack(2, 'Subtraction');
        let b = this._stack.pop();
        let a = this._stack.pop();
        this._stack.push(a - b);
        i++;
        continue;
      }
      if (word === '*') {
        this._requireStack(2, 'Multiplication');
        let b = this._stack.pop();
        let a = this._stack.pop();
        this._stack.push(a * b);
        i++;
        continue;
      }
      if (word === '/') {
        this._requireStack(2, 'Division');
        let b = this._stack.pop();
        let a = this._stack.pop();
        if (b === 0) {
          throw new Error('Division by zero');
        }
        // Integer division, truncate toward zero
        this._stack.push(Math.trunc(a / b));
        i++;
        continue;
      }

      // Stack manipulation
      if (word === 'dup') {
        this._requireStack(1, 'DUP');
        this._stack.push(this._stack[this._stack.length - 1]);
        i++;
        continue;
      }
      if (word === 'drop') {
        this._requireStack(1, 'DROP');
        this._stack.pop();
        i++;
        continue;
      }
      if (word === 'swap') {
        this._requireStack(2, 'SWAP');
        let b = this._stack.pop();
        let a = this._stack.pop();
        this._stack.push(b);
        this._stack.push(a);
        i++;
        continue;
      }
      if (word === 'over') {
        this._requireStack(2, 'OVER');
        let a = this._stack[this._stack.length - 2];
        this._stack.push(a);
        i++;
        continue;
      }

      // Word definition
      if (word === ':') {
        // Find the next ';'
        let end = tokens.indexOf(';', i);
        if (end === -1) {
          throw new Error('Unterminated word definition');
        }
        let name = normalizeWord(tokens[i + 1]);
        if (isNumber(name)) {
          throw new Error('Cannot redefine numbers');
        }
        let definition = tokens.slice(i + 2, end).map(normalizeWord);
        this._words[name] = definition;
        i = end + 1;
        continue;
      }

      // User-defined word
      if (this._words.hasOwnProperty(word)) {
        // Insert the definition tokens in place of the word
        tokens.splice(i, 1, ...this._words[word]);
        // Do not increment i, as we want to process the first token of the definition next
        continue;
      }

      throw new Error(`Unknown word: ${token}`);
    }
  }

  get stack() {
    // Return a copy to prevent external mutation
    return [...this._stack];
  }

  _requireStack(n, op) {
    if (this._stack.length < n) {
      throw new Error('Stack empty');
    }
  }

  _tokenize(input) {
    // Split on whitespace, but keep ':' and ';' as separate tokens
    // e.g. ": foo 1 2 ;" => [":", "foo", "1", "2", ";"]
    let tokens = [];
    let re = /(:|;)|([^\s:;]+)/g;
    let match;
    while ((match = re.exec(input)) !== null) {
      if (match[1]) {
        tokens.push(match[1]);
      } else if (match[2]) {
        tokens.push(match[2]);
      }
    }
    return tokens;
  }
}
