//
// This is only a SKELETON file for the 'Two Bucket' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class TwoBucket {
  constructor(bucketOneCap, bucketTwoCap, goal, startBucket) {
    this.bucketOneCap = bucketOneCap;
    this.bucketTwoCap = bucketTwoCap;
    this.goal = goal;
    this.startBucket = startBucket;
    this.result = this._solve();
  }

  solve() {
    return this.result;
  }

  _solve() {
    // Helper to simulate the process
    // Returns {moves, goalBucket, otherBucket}
    // Try both strategies: start with bucket one or two, as per input

    // We'll use a BFS to avoid cycles and to ensure minimum moves
    const cap1 = this.bucketOneCap;
    const cap2 = this.bucketTwoCap;
    const goal = this.goal;
    const start = this.startBucket;

    // State: [bucket1, bucket2]
    // visited: Set of "b1,b2"
    // Each queue entry: {b1, b2, moves, lastAction}
    // lastAction is not strictly needed, but could help for debugging

    // The rule: after an action, may not arrive at a state where the initial starting bucket is empty and the other bucket is full.

    // Initial state
    let initial;
    if (start === 'one') {
      initial = { b1: cap1, b2: 0, moves: 1 };
    } else {
      initial = { b1: 0, b2: cap2, moves: 1 };
    }

    const queue = [initial];
    const visited = new Set();
    visited.add(`${initial.b1},${initial.b2}`);

    while (queue.length > 0) {
      const { b1, b2, moves } = queue.shift();

      // Check for goal
      if (b1 === goal) {
        return {
          moves,
          goalBucket: 'one',
          otherBucket: b2
        };
      }
      if (b2 === goal) {
        return {
          moves,
          goalBucket: 'two',
          otherBucket: b1
        };
      }

      // Generate all possible next states (actions)
      const nextStates = [];

      // 1. Fill bucket one
      if (b1 < cap1) {
        nextStates.push({ b1: cap1, b2, moves: moves + 1 });
      }
      // 2. Fill bucket two
      if (b2 < cap2) {
        nextStates.push({ b1, b2: cap2, moves: moves + 1 });
      }
      // 3. Empty bucket one
      if (b1 > 0) {
        nextStates.push({ b1: 0, b2, moves: moves + 1 });
      }
      // 4. Empty bucket two
      if (b2 > 0) {
        nextStates.push({ b1, b2: 0, moves: moves + 1 });
      }
      // 5. Pour bucket one -> bucket two
      if (b1 > 0 && b2 < cap2) {
        const pour = Math.min(b1, cap2 - b2);
        nextStates.push({ b1: b1 - pour, b2: b2 + pour, moves: moves + 1 });
      }
      // 6. Pour bucket two -> bucket one
      if (b2 > 0 && b1 < cap1) {
        const pour = Math.min(b2, cap1 - b1);
        nextStates.push({ b1: b1 + pour, b2: b2 - pour, moves: moves + 1 });
      }

      for (const state of nextStates) {
        // Rule: may not arrive at a state where the initial starting bucket is empty and the other bucket is full
        if (
          (start === 'one' && state.b1 === 0 && state.b2 === cap2) ||
          (start === 'two' && state.b2 === 0 && state.b1 === cap1)
        ) {
          continue;
        }
        const key = `${state.b1},${state.b2}`;
        if (!visited.has(key)) {
          visited.add(key);
          queue.push(state);
        }
      }
    }

    // If we get here, no solution
    throw new Error('No solution');
  }
}
