//
// This is only a SKELETON file for the 'Complex Numbers' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class ComplexNumber {
  constructor(real, imag) {
    this._real = real;
    this._imag = imag;
  }

  get real() {
    return this._real;
  }

  get imag() {
    return this._imag;
  }

  add(other) {
    return new ComplexNumber(this._real + other.real, this._imag + other.imag);
  }

  sub(other) {
    return new ComplexNumber(this._real - other.real, this._imag - other.imag);
  }

  mul(other) {
    // (a + ib) * (c + id) = (ac - bd) + (bc + ad)i
    const a = this._real;
    const b = this._imag;
    const c = other.real;
    const d = other.imag;
    return new ComplexNumber(a * c - b * d, b * c + a * d);
  }

  div(other) {
    // (a + ib) / (c + id) = [(ac + bd) / (c^2 + d^2)] + [(bc - ad) / (c^2 + d^2)]i
    const a = this._real;
    const b = this._imag;
    const c = other.real;
    const d = other.imag;
    const denominator = c * c + d * d;
    return new ComplexNumber(
      (a * c + b * d) / denominator,
      (b * c - a * d) / denominator
    );
  }

  get abs() {
    // |z| = sqrt(a^2 + b^2)
    return Math.hypot(this._real, this._imag);
  }

  get conj() {
    // conjugate: a - b*i
    return new ComplexNumber(this._real, -this._imag);
  }

  get exp() {
    // e^(a + ib) = e^a * (cos(b) + i*sin(b))
    const eToA = Math.exp(this._real);
    return new ComplexNumber(
      eToA * Math.cos(this._imag),
      eToA * Math.sin(this._imag)
    );
  }
}
