namespace meetup {

using namespace std::chrono;

static int days_in_month(int year, int month) {
    // Handle leap years for February
    static const int days_in_months[] = { 31,28,31,30,31,30,31,31,30,31,30,31 };
    if (month == 2) {
        // Leap year check
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))
            return 29;
    }
    return days_in_months[month - 1];
}

year_month_day meetup_day(int year, int month, weekday wd, Week week) {
    year_month ym{year, month};
    int start_day = 1;
    int end_day = days_in_month(year, month);

    switch (week) {
        case Week::first:
            start_day = 1;
            end_day = 7;
            break;
        case Week::second:
            start_day = 8;
            end_day = 14;
            break;
        case Week::third:
            start_day = 15;
            end_day = 21;
            break;
        case Week::fourth:
            start_day = 22;
            end_day = 28;
            break;
        case Week::last:
            start_day = end_day - 6;
            // end_day remains as last day of month
            break;
        case Week::teenth:
            start_day = 13;
            end_day = 19;
            break;
    }

    for (int d = start_day; d <= end_day; ++d) {
        year_month_day ymd{year, month, day{d}};
        if (weekday{ymd} == wd) {
            return ymd;
        }
    }
