class CircularBuffer<T> {

    private final Object[] buffer;
    private final int capacity;
    private int head;
    private int tail;
    private int size;

    CircularBuffer(final int size) {
        if (size <= 0) {
            throw new IllegalArgumentException("Buffer size must be greater than 0.");
        }
        this.capacity = size;
        this.buffer = new Object[size];
        this.head = 0;
        this.tail = 0;
        this.size = 0;
    }

    T read() throws BufferIOException {
        if (size == 0) {
            throw new BufferIOException("Buffer is empty.");
        }
        @SuppressWarnings("unchecked")
        T value = (T) buffer[head];
        buffer[head] = null;
        head = (head + 1) % capacity;
        size--;
        return value;
    }

    void write(T data) throws BufferIOException {
        if (data == null) {
            return;
        }
        if (size == capacity) {
            throw new BufferIOException("Buffer is full.");
        }
        buffer[tail] = data;
        tail = (tail + 1) % capacity;
        size++;
    }

    void overwrite(T data) {
        if (data == null) {
            return;
        }
        if (size == capacity) {
            // Overwrite the oldest value
            buffer[tail] = data;
            tail = (tail + 1) % capacity;
            head = tail; // head always points to the oldest element
        } else {
            buffer[tail] = data;
            tail = (tail + 1) % capacity;
            size++;
        }
    }

    void clear() {
        for (int i = 0; i < capacity; i++) {
            buffer[i] = null;
        }
        head = 0;
        tail = 0;
        size = 0;
    }

}

class BufferIOException extends Exception {
    BufferIOException(String message) {
        super(message);
    }
}
