//
// This is only a SKELETON file for the 'List Ops' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class List {
  constructor(values = []) {
    this.values = values;
  }

  append(other) {
    // Returns a new List with other's values appended to this list's values
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = this.values[i];
    }
    for (let j = 0; j < other.values.length; j++) {
      result[result.length] = other.values[j];
    }
    return new List(result);
  }

  concat(lists) {
    // lists is an array of List instances
    let result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = this.values[i];
    }
    for (let i = 0; i < lists.values.length; i++) {
      const list = lists.values[i];
      for (let j = 0; j < list.values.length; j++) {
        result[result.length] = list.values[j];
      }
    }
    return new List(result);
  }

  filter(fn) {
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      if (fn(this.values[i])) {
        result[result.length] = this.values[i];
      }
    }
    return new List(result);
  }

  map(fn) {
    const result = [];
    for (let i = 0; i < this.values.length; i++) {
      result[result.length] = fn(this.values[i]);
    }
    return new List(result);
  }

  length() {
    let count = 0;
    for (let i = 0; i < this.values.length; i++) {
      count++;
    }
    return count;
  }

  foldl(fn, acc) {
    let result = acc;
    for (let i = 0; i < this.values.length; i++) {
      result = fn(result, this.values[i]);
    }
    return result;
  }

  foldr(fn, acc) {
    let result = acc;
    for (let i = this.values.length - 1; i >= 0; i--) {
      result = fn(this.values[i], result);
    }
    return result;
  }

  reverse() {
    const result = [];
    for (let i = this.values.length - 1; i >= 0; i--) {
      result[result.length] = this.values[i];
    }
    return new List(result);
  }
}
