    private final Set<T> set;

    CustomSet() {
        this.set = new HashSet<>();
    }

    CustomSet(Collection<T> data) {
        this.set = new HashSet<>(data);
    }

    boolean isEmpty() {
        return set.isEmpty();
    }

    boolean contains(T element) {
        return set.contains(element);
    }

    boolean isDisjoint(CustomSet<T> other) {
        for (T elem : set) {
            if (other.contains(elem)) {
                return false;
            }
        }
        return true;
    }

    boolean add(T element) {
        return set.add(element);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof CustomSet)) return false;
        CustomSet<?> other = (CustomSet<?>) obj;
        return set.equals(other.set);
    }

    @Override
    public int hashCode() {
        return Objects.hash(set);
    }

    CustomSet<T> getIntersection(CustomSet<T> other) {
        CustomSet<T> result = new CustomSet<>();
        for (T elem : set) {
            if (other.contains(elem)) {
                result.add(elem);
            }
        }
        return result;
    }

    CustomSet<T> getUnion(CustomSet<T> other) {
        CustomSet<T> result = new CustomSet<>(this.set);
        for (T elem : other.set) {
            result.add(elem);
        }
        return result;
    }

    CustomSet<T> getDifference(CustomSet<T> other) {
        CustomSet<T> result = new CustomSet<>();
        for (T elem : set) {
            if (!other.contains(elem)) {
                result.add(elem);
            }
        }
        return result;
    }

    boolean isSubset(CustomSet<T> other) {
        // An empty set is a subset of any set (including another empty set)
        if (this.set.isEmpty()) {
            return true;
        }
        // A non-empty set cannot be a subset of an empty set
        if (other.set.isEmpty() && !this.set.isEmpty()) {
            return false;
        }
        return other.set.containsAll(this.set);
    }
}
