package bookstore

func Cost(books []int) int {
	if len(books) == 0 {
		return 0
	}

	// Count how many copies of each book (0-4)
	counts := make([]int, 5)
	for _, b := range books {
		counts[b]++
	}

	// Memoization to avoid recomputation
	memo := map[[5]int]int{}

	var minCost func([5]int) int
	minCost = func(state [5]int) int {
		// Check memo
		if v, ok := memo[state]; ok {
			return v
		}

		// Check if all books are bought
		done := true
		for _, c := range state {
			if c > 0 {
				done = false
				break
			}
		}
		if done {
			return 0
		}

		best := 1 << 30 // large number

		// Try all possible group sizes (from 5 down to 1)
		for size := 5; size >= 1; size-- {
			// Find which books can be grouped
			indices := []int{}
			for i, c := range state {
				if c > 0 {
					indices = append(indices, i)
					if len(indices) == size {
						break
					}
				}
			}
			if len(indices) < size {
				continue
			}

			// Form a new state with one less of each selected book
			newState := state
			for _, idx := range indices {
				newState[idx]--
			}

			// Calculate price for this group
			groupPrice := groupCost(size)
			total := groupPrice + minCost(newState)
			if total < best {
				best = total
			}
		}

		memo[state] = best
		return best
	}

	var arr [5]int
	copy(arr[:], counts)
	return minCost(arr)
}

// groupCost returns the cost in cents for a group of n different books
func groupCost(n int) int {
	base := 800 * n
	switch n {
	case 2:
		return base * 95 / 100 // 5% discount
	case 3:
		return base * 90 / 100 // 10% discount
	case 4:
		return base * 80 / 100 // 20% discount
	case 5:
		return base * 75 / 100 // 25% discount
	default:
		return base // no discount
	}
}
