    is_open_ = true;
    balance_ = 0;
}

void Bankaccount::close() {
    std::lock_guard<std::mutex> lock(mtx_);
    is_open_ = false;
}

std::optional<int> Bankaccount::balance() const {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!is_open_) {
        return std::nullopt;
    }
    return balance_;
}

bool Bankaccount::deposit(int amount) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!is_open_ || amount < 0) {
        return false;
    }
    balance_ += amount;
    return true;
}

bool Bankaccount::withdraw(int amount) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!is_open_ || amount < 0 || amount > balance_) {
        return false;
    }
    balance_ -= amount;
    return true;
}

} // namespace Bankaccount
