  '', 'thousand', 'million', 'billion', 'trillion'
];

const MAX = 999999999999;
const MIN = 0;

function sayBelowThousand(n) {
  let result = [];
  if (n >= 100) {
    result.push(ONES[Math.floor(n / 100)] + ' hundred');
    n = n % 100;
    if (n > 0) {
      result.push('');
    }
  }
  if (n >= 20) {
    let tens = Math.floor(n / 10);
    let ones = n % 10;
    if (ones > 0) {
      result.push(TENS[tens] + '-' + ONES[ones]);
    } else {
      result.push(TENS[tens]);
    }
  } else if (n > 0 || result.length === 0) {
    result.push(ONES[n]);
  }
  return result.join(' ').trim();
}

function chunkThousands(n) {
  let chunks = [];
  while (n > 0) {
    chunks.push(n % 1000);
    n = Math.floor(n / 1000);
  }
  return chunks;
}

export const say = (n) => {
  if (typeof n !== 'number' || n < MIN || n > MAX || !Number.isInteger(n)) {
    throw new Error('Number must be between 0 and 999,999,999,999.');
  }
  if (n === 0) {
    return ONES[0];
  }

  let chunks = chunkThousands(n);
  let words = [];

  for (let i = chunks.length - 1; i >= 0; i--) {
    let chunk = chunks[i];
    if (chunk === 0) continue;
    let chunkWords = sayBelowThousand(chunk);
    let scale = SCALES[i];
    if (scale) {
      words.push(chunkWords + ' ' + scale);
    } else {
      words.push(chunkWords);
    }
  }

  return words.join(' ').replace(/\s+/g, ' ').trim();
