import java.util.*;

public class SgfParsing {
    public SgfNode parse(String input) throws SgfParsingException {
        if (input == null || input.isEmpty()) {
            throw new SgfParsingException("Input is empty");
        }
        Parser parser = new Parser(input);
        SgfNode node = parser.parseTree();
        if (!parser.isAtEnd()) {
            throw new SgfParsingException("Unexpected content after end of SGF tree");
        }
        return node;
    }

    // Helper parser class
    private static class Parser {
        private final String input;
        private int pos;

        Parser(String input) {
            this.input = input;
            this.pos = 0;
        }

        boolean isAtEnd() {
            return pos >= input.length();
        }

        char peek() {
            if (isAtEnd()) return '\0';
            return input.charAt(pos);
        }

        char next() {
            if (isAtEnd()) return '\0';
            return input.charAt(pos++);
        }

        void expect(char c) throws SgfParsingException {
            if (isAtEnd() || input.charAt(pos) != c) {
                throw new SgfParsingException("Expected '" + c + "' at position " + pos);
            }
            pos++;
        }

        // Parse a whole SGF tree (starts with '(')
        SgfNode parseTree() throws SgfParsingException {
            skipWhitespace();
            expect('(');
            List<SgfNode> variations = new ArrayList<>();
            while (true) {
                skipWhitespace();
                if (peek() == ';') {
                    variations.add(parseSequence());
                } else if (peek() == '(') {
                    variations.add(parseTree());
                } else if (peek() == ')') {
                    next();
                    break;
                } else if (isAtEnd()) {
                    throw new SgfParsingException("Unexpected end of input inside tree");
                } else {
                    throw new SgfParsingException("Unexpected character '" + peek() + "' at position " + pos);
                }
            }
            if (variations.isEmpty()) {
                throw new SgfParsingException("Tree must have at least one node");
            }
            // If only one variation, return it directly
            if (variations.size() == 1) {
                return variations.get(0);
            } else {
                // Root node with no properties, children are variations
                return new SgfNode(new LinkedHashMap<>(), variations);
            }
        }

        // Parse a sequence of nodes (e.g. ;A[];B[];C[])
        SgfNode parseSequence() throws SgfParsingException {
            SgfNode first = parseNode();
            SgfNode current = first;
            while (true) {
                skipWhitespace();
                if (peek() == ';') {
                    SgfNode nextNode = parseNode();
                    current.getChildren().add(nextNode);
                    current = nextNode;
                } else if (peek() == '(' || peek() == ')' || isAtEnd()) {
                    break;
                } else {
                    throw new SgfParsingException("Unexpected character '" + peek() + "' in sequence at position " + pos);
                }
            }
            return first;
        }

        // Parse a single node (starts with ';')
        SgfNode parseNode() throws SgfParsingException {
            expect(';');
            skipWhitespace();
            Map<String, List<String>> properties = new LinkedHashMap<>();
            while (true) {
                skipWhitespace();
                if (isUppercase(peek())) {
                    String key = parsePropIdent();
                    List<String> values = new ArrayList<>();
                    do {
                        skipWhitespace();
                        if (peek() != '[') {
                            throw new SgfParsingException("Expected '[' after property key at position " + pos);
                        }
                        values.add(parsePropValue());
                        skipWhitespace();
                    } while (peek() == '[');
                    if (properties.containsKey(key)) {
                        throw new SgfParsingException("Duplicate property key: " + key);
                    }
                    properties.put(key, values);
                } else {
                    break;
                }
            }
            return new SgfNode(properties, new ArrayList<>());
        }

        String parsePropIdent() throws SgfParsingException {
            int start = pos;
            while (isUppercase(peek())) {
                pos++;
            }
            if (start == pos) {
                throw new SgfParsingException("Expected property identifier at position " + pos);
            }
            return input.substring(start, pos);
        }

        String parsePropValue() throws SgfParsingException {
            expect('[');
            StringBuilder sb = new StringBuilder();
            boolean escaping = false;
            while (true) {
                if (isAtEnd()) {
                    throw new SgfParsingException("Unterminated property value");
                }
                char c = next();
                if (escaping) {
                    if (c == '\n') {
                        // Remove backslash and newline
                        // Do not append anything
                    } else if (c == '\t' || c == '\r' || c == '\f') {
                        // Convert to space
                        sb.append(' ');
                    } else {
                        sb.append(c);
                    }
                    escaping = false;
                } else if (c == '\\') {
                    escaping = true;
                } else if (c == ']') {
                    break;
                } else if (c == '\n') {
                    sb.append('\n');
                } else if (c == '\t' || c == '\r' || c == '\f') {
                    sb.append(' ');
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        void skipWhitespace() {
            while (!isAtEnd() && (peek() == ' ' || peek() == '\t' || peek() == '\r' || peek() == '\f')) {
                pos++;
            }
        }

        boolean isUppercase(char c) {
            return c >= 'A' && c <= 'Z';
        }
    }
}
