#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    rolls: Vec<u16>,
    current_frame: usize,
    is_complete: bool,
}

impl BowlingGame {
    pub fn new() -> Self {
        BowlingGame {
            rolls: Vec::with_capacity(21), // max rolls in a game
            current_frame: 0,
            is_complete: false,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.is_complete {
            return Err(Error::GameComplete);
        }
        if pins > 10 {
            return Err(Error::NotEnoughPinsLeft);
        }

        // Check for not enough pins left in the frame
        let mut frame = 0;
        let mut i = 0;
        let mut in_tenth = false;
        while frame < 9 && i < self.rolls.len() {
            if self.rolls[i] == 10 {
                i += 1;
            } else {
                i += 2;
            }
            frame += 1;
        }
        if frame == 9 {
            in_tenth = true;
        }

        if in_tenth {
            // Tenth frame logic
            let tenth_rolls = &self.rolls[i..];
            match tenth_rolls.len() {
                0 => {
                    // first roll, always allowed
                }
                1 => {
                    // second roll, check if sum > 10 unless first was strike
                    if tenth_rolls[0] != 10 && tenth_rolls[0] + pins > 10 {
                        return Err(Error::NotEnoughPinsLeft);
                    }
                }
                2 => {
                    // third roll only allowed if strike or spare in first two
                    let first = tenth_rolls[0];
                    let second = tenth_rolls[1];
                    if first == 10 || first + second == 10 {
                        // allowed, but if second was not strike, check pins
                        if first != 10 && second != 10 && second + pins > 10 {
                            return Err(Error::NotEnoughPinsLeft);
                        }
                    } else {
                        return Err(Error::GameComplete);
                    }
                }
                3 => {
                    return Err(Error::GameComplete);
                }
                _ => {}
            }
        } else {
            // Not in tenth frame
            let mut frame_rolls = 0;
            let mut frame_pins = 0;
            let mut idx = i;
            while idx < self.rolls.len() {
                if self.rolls[idx] == 10 {
                    frame_rolls = 1;
                    frame_pins = 10;
                    break;
                } else {
                    frame_rolls += 1;
                    frame_pins += self.rolls[idx];
                    if frame_rolls == 2 {
                        break;
                    }
                }
                idx += 1;
            }
            if frame_rolls == 1 && frame_pins < 10 && frame_pins + pins > 10 {
                return Err(Error::NotEnoughPinsLeft);
            }
            if frame_rolls == 0 && pins > 10 {
                return Err(Error::NotEnoughPinsLeft);
            }
        }

        self.rolls.push(pins);

        // Check if game is complete
        if self.is_game_complete() {
            self.is_complete = true;
        }

        Ok(())
    }

    pub fn score(&self) -> Option<u16> {
        if !self.is_game_complete() {
            return None;
        }
        let mut score = 0;
        let mut roll_index = 0;
        for frame in 0..10 {
            if roll_index >= self.rolls.len() {
                return None;
            }
            if self.rolls[roll_index] == 10 {
                // Strike
                if roll_index + 2 >= self.rolls.len() {
                    return None;
                }
                score += 10 + self.rolls[roll_index + 1] + self.rolls[roll_index + 2];
                roll_index += 1;
            } else if roll_index + 1 < self.rolls.len() && self.rolls[roll_index] + self.rolls[roll_index + 1] == 10 {
                // Spare
                if roll_index + 2 >= self.rolls.len() {
                    return None;
                }
                score += 10 + self.rolls[roll_index + 2];
                roll_index += 2;
            } else if roll_index + 1 < self.rolls.len() {
                // Open frame
                score += self.rolls[roll_index] + self.rolls[roll_index + 1];
                roll_index += 2;
            } else {
                return None;
            }
        }
        Some(score)
    }

    fn is_game_complete(&self) -> bool {
        let mut roll_index = 0;
        for frame in 0..9 {
            if roll_index >= self.rolls.len() {
                return false;
            }
            if self.rolls[roll_index] == 10 {
                roll_index += 1;
            } else {
                if roll_index + 1 >= self.rolls.len() {
                    return false;
                }
                roll_index += 2;
            }
        }
        // Tenth frame
        if roll_index >= self.rolls.len() {
            return false;
        }
        let first = self.rolls[roll_index];
        let second = if roll_index + 1 < self.rolls.len() {
            self.rolls[roll_index + 1]
        } else {
            return false;
        };
        if first == 10 {
            // Strike in 10th, need two more rolls
            if roll_index + 2 >= self.rolls.len() {
                return false;
            }
            // Only three rolls allowed in 10th
            return self.rolls.len() == roll_index + 3;
        } else if first + second == 10 {
            // Spare in 10th, need one more roll
            if roll_index + 2 >= self.rolls.len() {
                return false;
            }
            return self.rolls.len() == roll_index + 3;
        } else {
            // Open frame, only two rolls
            return self.rolls.len() == roll_index + 2;
        }
    }
}
