bool chess_board::can_attack() const {
    // Same row
    if (white_pos.first == black_pos.first) {
        return true;
    }
    // Same column
    if (white_pos.second == black_pos.second) {
        return true;
    }
    // Same diagonal
    if (std::abs(white_pos.first - black_pos.first) == std::abs(white_pos.second - black_pos.second)) {
        return true;
    }
    return false;
}

