package scale

import (
	"strings"
	"unicode"
)

var sharpScale = []string{"A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"}
var flatScale  = []string{"A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"}

var useSharps = map[string]bool{
	// Major
	"C": true, "G": true, "D": true, "A": true, "E": true, "B": true, "F#": true,
	// Minor
	"A": true, "E": true, "B": true, "F#": true, "C#": true, "G#": true, "D#": true,
}

var useFlats = map[string]bool{
	// Major
	"F": true, "Bb": true, "Eb": true, "Ab": true, "Db": true, "Gb": true,
	// Minor
	"D": true, "G": true, "C": true, "F": true, "Bb": true, "Eb": true,
}

func normalizeTonic(tonic string) string {
	if len(tonic) == 0 {
		return ""
	}
	runes := []rune(tonic)
	upper := string(unicode.ToUpper(runes[0]))
	if len(runes) > 1 {
		return upper + strings.ToLower(string(runes[1:]))
	}
	return upper
}

func getScale(tonic string) []string {
	t := normalizeTonic(tonic)
	if useSharps[t] {
		return sharpScale
	}
	if useFlats[t] {
		return flatScale
	}
	// Default: C and a use sharps
	return sharpScale
}

func indexOf(scale []string, note string) int {
	for i, n := range scale {
		if n == note {
			return i
		}
	}
	return -1
}

func Scale(tonic, interval string) []string {
	t := normalizeTonic(tonic)
	scale := getScale(t)
	start := indexOf(scale, t)
	if start == -1 {
		return []string{}
	}

	// Chromatic scale (no interval string)
	if interval == "" {
		result := make([]string, 12)
		for i := 0; i < 12; i++ {
			result[i] = scale[(start+i)%12]
		}
		return result
	}

	// Diatonic or custom scale (with interval string)
	result := []string{scale[start]}
	pos := start
	for _, step := range interval {
		var inc int
		switch step {
		case 'm':
			inc = 1
		case 'M':
			inc = 2
		case 'A':
			inc = 3
		default:
			inc = 1
		}
		pos = (pos + inc) % 12
		result = append(result, scale[pos])
	}
	return result
}
