package bowling

import (
	"errors"
)

type Game struct {
	rolls []int
}

func NewGame() *Game {
	return &Game{
		rolls: make([]int, 0, 21), // max rolls in a game is 21
	}
}

func (g *Game) Roll(pins int) error {
	if pins < 0 || pins > 10 {
		return errors.New("invalid number of pins")
	}
	// Check for too many rolls
	if len(g.rolls) >= 21 {
		// Might be allowed if 10th frame is a strike or spare, so check
		if !g.canRollExtra() {
			return errors.New("cannot roll after game is over")
		}
	}
	g.rolls = append(g.rolls, pins)
	return nil
}

func (g *Game) canRollExtra() bool {
	// Only called if len(g.rolls) >= 21
	// Check if 10th frame was a strike or spare
	frame := 0
	i := 0
	for frame < 9 && i < len(g.rolls) {
		if g.rolls[i] == 10 {
			i++
		} else {
			i += 2
		}
		frame++
	}
	// Now i is at the start of the 10th frame
	if i >= len(g.rolls) {
		return false
	}
	// 10th frame: up to 3 rolls
	rollsInTenth := len(g.rolls) - i
	if g.rolls[i] == 10 {
		// Strike in first roll of 10th frame: up to 3 rolls
		return rollsInTenth < 3
	} else if rollsInTenth >= 2 && g.rolls[i]+g.rolls[i+1] == 10 {
		// Spare in 10th frame: up to 3 rolls
		return rollsInTenth < 3
	} else {
		// Open frame: only 2 rolls allowed
		return rollsInTenth < 2
	}
}

func (g *Game) Score() (int, error) {
	score := 0
	rollIndex := 0
	for frame := 0; frame < 10; frame++ {
		if rollIndex >= len(g.rolls) {
			return 0, errors.New("not enough rolls to score the game")
		}
		if g.rolls[rollIndex] == 10 { // Strike
			if rollIndex+2 >= len(g.rolls) {
				return 0, errors.New("not enough rolls to score strike bonus")
			}
			score += 10 + g.rolls[rollIndex+1] + g.rolls[rollIndex+2]
			rollIndex++
		} else if rollIndex+1 < len(g.rolls) && g.rolls[rollIndex]+g.rolls[rollIndex+1] == 10 { // Spare
			if rollIndex+2 >= len(g.rolls) {
				return 0, errors.New("not enough rolls to score spare bonus")
			}
			score += 10 + g.rolls[rollIndex+2]
			rollIndex += 2
		} else if rollIndex+1 < len(g.rolls) { // Open frame
			score += g.rolls[rollIndex] + g.rolls[rollIndex+1]
			rollIndex += 2
		} else {
			return 0, errors.New("not enough rolls to complete frame")
		}
	}
	return score, nil
}
