          if (frame.length < 3) {
            throw new Error('Score cannot be taken until the end of the game');
          }
        } else if (frame[0] === 10 || frame[0] + frame[1] === 10) {
          // Strike or spare, need third roll
          if (frame.length < 3) {
            throw new Error('Score cannot be taken until the end of the game');
          }
        }
      }
    } else if (frame.length === 1) {
      throw new Error('Score cannot be taken until the end of the game');
    } else if (frame.length === 3) {
      // All good
    }

    let score = 0;
    let rollIndex = 0;
    for (let frame = 0; frame < 10; frame++) {
      if (this.rolls[rollIndex] === 10) {
        // Strike
        score += 10 + (this.rolls[rollIndex + 1] || 0) + (this.rolls[rollIndex + 2] || 0);
        rollIndex += 1;
      } else if ((this.rolls[rollIndex] || 0) + (this.rolls[rollIndex + 1] || 0) === 10) {
        // Spare
        score += 10 + (this.rolls[rollIndex + 2] || 0);
        rollIndex += 2;
      } else {
        // Open frame
        score += (this.rolls[rollIndex] || 0) + (this.rolls[rollIndex + 1] || 0);
        rollIndex += 2;
      }
    }
    return score;
  }
