bool school::add(const std::string& name, int grade) {
    // Check if student already exists
    if (student_to_grade_.count(name) > 0) {
        return false;
    }
    student_to_grade_[name] = grade;
    students_by_grade_[grade].push_back(name);
    // Keep the vector sorted
    std::sort(students_by_grade_[grade].begin(), students_by_grade_[grade].end());
    return true;
}

std::vector<std::string> school::grade(int grade) const {
    auto it = students_by_grade_.find(grade);
    if (it == students_by_grade_.end()) {
        return {};
    }
    return it->second;
}

std::vector<std::string> school::roster() const {
    std::vector<std::string> all_students;
    for (const auto& grade_students : students_by_grade_) {
        all_students.insert(all_students.end(), grade_students.second.begin(), grade_students.second.end());
    }
    return all_students;
}

std::map<int, std::vector<std::string>> school::grades() const {
    return students_by_grade_;
}

}  // namespace grade_school
