package forth

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"errors"
)

type wordDef []string

type forthEnv struct {
	stack []int
	words map[string]wordDef
}

func isNumber(token string) bool {
	if len(token) == 0 {
		return false
	}
	// allow negative numbers
	if token[0] == '-' && len(token) > 1 {
		token = token[1:]
	}
	for _, r := range token {
		if !unicode.IsDigit(r) {
			return false
		}
	}
	return true
}

func toLowerSlice(tokens []string) []string {
	out := make([]string, len(tokens))
	for i, t := range tokens {
		out[i] = strings.ToLower(t)
	}
	return out
}

func (env *forthEnv) evalToken(token string, callStack map[string]bool) error {
	tokenLower := strings.ToLower(token)
	switch tokenLower {
	case "+":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a+b)
	case "-":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a-b)
	case "*":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a*b)
	case "/":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		a, b := env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
		if b == 0 {
			return errors.New("divide by zero")
		}
		env.stack = env.stack[:len(env.stack)-2]
		env.stack = append(env.stack, a/b)
	case "dup":
		if len(env.stack) < 1 {
			return errors.New("stack underflow")
		}
		env.stack = append(env.stack, env.stack[len(env.stack)-1])
	case "drop":
		if len(env.stack) < 1 {
			return errors.New("stack underflow")
		}
		env.stack = env.stack[:len(env.stack)-1]
	case "swap":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		env.stack[len(env.stack)-1], env.stack[len(env.stack)-2] = env.stack[len(env.stack)-2], env.stack[len(env.stack)-1]
	case "over":
		if len(env.stack) < 2 {
			return errors.New("stack underflow")
		}
		env.stack = append(env.stack, env.stack[len(env.stack)-2])
	default:
		if def, ok := env.words[tokenLower]; ok {
			// Prevent infinite recursion
			if callStack[tokenLower] {
				return fmt.Errorf("infinite recursion detected for word: %s", tokenLower)
			}
			callStack[tokenLower] = true
			for _, t := range def {
				if err := env.evalToken(t, callStack); err != nil {
					return err
				}
			}
			delete(callStack, tokenLower)
		} else if isNumber(token) {
			val, _ := strconv.Atoi(token)
			env.stack = append(env.stack, val)
		} else {
			return fmt.Errorf("undefined word: %s", token)
		}
	}
	return nil
}

func parseDefinition(tokens []string, i int) (string, []string, int, error) {
	// tokens[i] == ":"
	if i+1 >= len(tokens) {
		return "", nil, i, errors.New("invalid definition: missing word name")
	}
	wordName := strings.ToLower(tokens[i+1])
	def := []string{}
	j := i + 2
	for ; j < len(tokens); j++ {
		if tokens[j] == ";" {
			break
		}
		def = append(def, tokens[j])
	}
	if j == len(tokens) {
		return "", nil, i, errors.New("invalid definition: missing ';'")
	}
	return wordName, toLowerSlice(def), j, nil
}

func Forth(input []string) ([]int, error) {
	env := &forthEnv{
		stack: []int{},
		words: make(map[string]wordDef),
	}

	// flatten input into tokens
	tokens := []string{}
	for _, line := range input {
		parts := strings.Fields(line)
		tokens = append(tokens, parts...)
	}

	for i := 0; i < len(tokens); i++ {
		token := tokens[i]
		if token == ":" {
			word, def, j, err := parseDefinition(tokens, i)
			if err != nil {
				return nil, err
			}
			// allow redefinition, but cannot redefine numbers
			if isNumber(word) {
				return nil, errors.New("cannot redefine numbers")
			}
			env.words[word] = def
			i = j // skip to after ';'
		} else {
			callStack := make(map[string]bool)
			if err := env.evalToken(token, callStack); err != nil {
				return nil, err
			}
		}
	}
	return env.stack, nil
}
