void chess_board::validate_position(const std::pair<int, int>& pos) {
    // Row and column must be between 0 and 7 (inclusive)
    if (pos.first < 0 || pos.first > 7) {
        throw std::domain_error("Row must be between 0 and 7");
    }
    if (pos.second < 0 || pos.second > 7) {
        throw std::domain_error("Column must be between 0 and 7");
    }
}

chess_board::chess_board(const std::pair<int, int>& white, const std::pair<int, int>& black)
    : white_pos(white), black_pos(black) 
{
    validate_position(white);
    validate_position(black);
    if (white == black) {
        throw std::domain_error("Queens cannot occupy the same position");
    }
}

std::pair<int, int> chess_board::white() const {
    return white_pos;
}

std::pair<int, int> chess_board::black() const {
    return black_pos;
}

bool chess_board::can_attack() const {
    // Same row
    if (white_pos.first == black_pos.first) {
        return true;
    }
    // Same column
    if (white_pos.second == black_pos.second) {
        return true;
    }
    // Same diagonal
    if (std::abs(white_pos.first - black_pos.first) == std::abs(white_pos.second - black_pos.second)) {
        return true;
    }
    return false;
}

}  // namespace queen_attack
