namespace meetup {

using namespace boost::gregorian;

scheduler::scheduler(int year, greg_month month)
    : m_year(year), m_month(month) {}

date scheduler::find_nth_weekday(int n, date_time::weekdays wd) const {
    // n = 1 for first, 2 for second, etc.
    date first_day(m_year, m_month, 1);
    int first_wd = first_day.day_of_week();
    int target_wd = static_cast<int>(wd);
    int days_to_add = (target_wd - first_wd + 7) % 7 + (n - 1) * 7;
    return first_day + date_duration(days_to_add);
}

date scheduler::find_last_weekday(date_time::weekdays wd) const {
    date first_day(m_year, m_month, 1);
    date next_month = m_month.as_number() == 12
        ? date(m_year + 1, 1, 1)
        : date(m_year, m_month.as_number() + 1, 1);
    date last_day = next_month - date_duration(1);
    int last_wd = last_day.day_of_week();
    int target_wd = static_cast<int>(wd);
    int days_to_subtract = (last_wd - target_wd + 7) % 7;
    return last_day - date_duration(days_to_subtract);
}

