package linkedlist

import (
	"errors"
)

// Element represents a node in the singly linked list.
type Element struct {
	Value int
	Next  *Element
}

// List represents the singly linked list.
type List struct {
	head *Element
	size int
}

// New creates a new linked list from a slice of integers.
// The first element in the slice will be the head of the list.
func New(elements []int) *List {
	list := &List{}
	// Insert elements in reverse order so the first element in the slice is the head.
	for i := len(elements) - 1; i >= 0; i-- {
		list.Push(elements[i])
	}
	return list
}

// Size returns the number of elements in the list.
func (l *List) Size() int {
	return l.size
}

// Push adds an element to the front (head) of the list.
func (l *List) Push(element int) {
	newElem := &Element{
		Value: element,
		Next:  l.head,
	}
	l.head = newElem
	l.size++
}

// Pop removes and returns the element at the front (head) of the list.
// Returns an error if the list is empty.
func (l *List) Pop() (int, error) {
	if l.head == nil {
		return 0, errors.New("cannot pop from an empty list")
	}
	val := l.head.Value
	l.head = l.head.Next
	l.size--
	return val, nil
}

// Array returns a slice containing the elements of the list in order.
func (l *List) Array() []int {
	result := make([]int, 0, l.size)
	for curr := l.head; curr != nil; curr = curr.Next {
		result = append(result, curr.Value)
	}
	return result
}

// Reverse returns a new list with the elements in reverse order.
func (l *List) Reverse() *List {
	reversed := &List{}
	for curr := l.head; curr != nil; curr = curr.Next {
		reversed.Push(curr.Value)
	}
	return reversed
}
