        public char data;
        public Tree left;
        public Tree right;

        public Tree(char data) {
            this.data = data;
        }

        public Tree(char data, Tree left, Tree right) {
            this.data = data;
            this.left = left;
            this.right = right;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Tree)) return false;
            Tree tree = (Tree) o;
            return data == tree.data &&
                    Objects.equals(left, tree.left) &&
                    Objects.equals(right, tree.right);
        }

        @Override
        public int hashCode() {
            return Objects.hash(data, left, right);
        }
    }

    public Tree treeFromTraversals(List<Character> preorderInput, List<Character> inorderInput) {
        if (preorderInput == null || inorderInput == null ||
            preorderInput.size() != inorderInput.size() ||
            preorderInput.isEmpty()) {
            return null;
        }
        return buildTree(preorderInput, 0, preorderInput.size() - 1,
                         inorderInput, 0, inorderInput.size() - 1);
    }

    private Tree buildTree(List<Character> preorder, int preStart, int preEnd,
                           List<Character> inorder, int inStart, int inEnd) {
        if (preStart > preEnd || inStart > inEnd) {
            return null;
        }

        char rootVal = preorder.get(preStart);
        Tree root = new Tree(rootVal);

        // Find the index of the root in inorder traversal
        int inRootIndex = inStart;
        while (inRootIndex <= inEnd && inorder.get(inRootIndex) != rootVal) {
            inRootIndex++;
        }

        int leftTreeSize = inRootIndex - inStart;

        root.left = buildTree(preorder, preStart + 1, preStart + leftTreeSize,
                              inorder, inStart, inRootIndex - 1);
        root.right = buildTree(preorder, preStart + leftTreeSize + 1, preEnd,
                               inorder, inRootIndex + 1, inEnd);

        return root;
    }
}
