import java.util.*;

class Tree {
    private final String label;
    private final List<Tree> children;

    public Tree(String label) {
        this(label, new ArrayList<>());
    }

    public Tree(String label, List<Tree> children) {
        this.label = label;
        this.children = children;
    }

    public static Tree of(String label) {
        return new Tree(label);
    }

    public static Tree of(String label, List<Tree> children) {
        return new Tree(label, children);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Tree tree = (Tree) o;
        return label.equals(tree.label)
                && children.equals(tree.children);
    }

    @Override
    public int hashCode() {
        return Objects.hash(label, children);
    }

    @Override
    public String toString() {
        return "Tree{" + label +
                ", " + children +
                "}";
    }

    public Tree fromPov(String fromNode) {
        // Find the path from root to fromNode
        List<Tree> path = new ArrayList<>();
        if (!findPathToNode(this, fromNode, path)) {
            throw new UnsupportedOperationException("Tree could not be reoriented");
        }
        // Rebuild the tree from the path, reversing parent-child relationships along the path
        return buildReparentedTree(path);
    }

    public List<String> pathTo(String fromNode, String toNode) {
        List<Tree> pathFrom = new ArrayList<>();
        List<Tree> pathTo = new ArrayList<>();
        if (!findPathToNode(this, fromNode, pathFrom) || !findPathToNode(this, toNode, pathTo)) {
            throw new UnsupportedOperationException("No path found");
        }
        // Find lowest common ancestor
        int i = 0;
        while (i < pathFrom.size() && i < pathTo.size() && pathFrom.get(i).label.equals(pathTo.get(i).label)) {
            i++;
        }
        List<String> result = new ArrayList<>();
        // Go up from fromNode to LCA (excluding LCA)
        for (int j = pathFrom.size() - 1; j >= i; j--) {
            result.add(pathFrom.get(j).label);
        }
        // Go down from LCA (including LCA) to toNode
        for (int j = i - 1; j < pathTo.size(); j++) {
            result.add(pathTo.get(j).label);
        }
        return result;
    }

    // Helper: find path from root to target node, store nodes in path
    private boolean findPathToNode(Tree node, String target, List<Tree> path) {
        path.add(node);
        if (node.label.equals(target)) {
            return true;
        }
        for (Tree child : node.children) {
            if (findPathToNode(child, target, path)) {
                return true;
            }
        }
        path.remove(path.size() - 1);
        return false;
    }

    // Helper: build the reparented tree from the path
    private Tree buildReparentedTree(List<Tree> path) {
        // path: root ... target
        Tree newRoot = cloneTree(path.get(path.size() - 1));
        Tree current = newRoot;
        for (int i = path.size() - 2; i >= 0; i--) {
            Tree parent = path.get(i);
            // Remove the child that is already in the path (to avoid cycles)
            List<Tree> siblings = new ArrayList<>();
            for (Tree child : parent.children) {
                if (!child.label.equals(current.label)) {
                    siblings.add(cloneTree(child));
                }
            }
            // The parent becomes a child of the current node, with its other children (except the one along the path)
            Tree parentAsChild = new Tree(parent.label, siblings);
            current.children.add(parentAsChild);
            current = parentAsChild;
        }
        return newRoot;
    }

    // Helper: deep clone a tree (including children)
    private Tree cloneTree(Tree node) {
        List<Tree> clonedChildren = new ArrayList<>();
        for (Tree child : node.children) {
            clonedChildren.add(cloneTree(child));
        }
        return new Tree(node.label, clonedChildren);
    }
}
