package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix type definition
type Matrix struct {
	data [][]int
	rows int
	cols int
}

// New creates a new Matrix from a string
func New(s string) (Matrix, error) {
	lines := strings.Split(strings.TrimSpace(s), "\n")
	if len(lines) == 0 {
		return Matrix{}, errors.New("input string is empty")
	}

	var matrixData [][]int
	var numCols int

	for i, line := range lines {
		fields := strings.Fields(line)
		if i == 0 {
			numCols = len(fields)
			if numCols == 0 {
				return Matrix{}, errors.New("no columns found")
			}
		} else if len(fields) != numCols {
			return Matrix{}, errors.New("inconsistent number of columns")
		}

		row := make([]int, numCols)
		for j, field := range fields {
			val, err := strconv.Atoi(field)
			if err != nil {
				return Matrix{}, errors.New("invalid integer value in matrix")
			}
			row[j] = val
		}
		matrixData = append(matrixData, row)
	}

	return Matrix{
		data: matrixData,
		rows: len(matrixData),
		cols: numCols,
	}, nil
}

// Cols returns a copy of the columns of the matrix
func (m Matrix) Cols() [][]int {
	if m.rows == 0 || m.cols == 0 {
		return [][]int{}
	}
	cols := make([][]int, m.cols)
	for i := 0; i < m.cols; i++ {
		col := make([]int, m.rows)
		for j := 0; j < m.rows; j++ {
			col[j] = m.data[j][i]
		}
		cols[i] = col
	}
	return cols
}

// Rows returns a copy of the rows of the matrix
func (m Matrix) Rows() [][]int {
	if m.rows == 0 {
		return [][]int{}
	}
	rows := make([][]int, m.rows)
	for i := 0; i < m.rows; i++ {
		row := make([]int, m.cols)
		copy(row, m.data[i])
		rows[i] = row
	}
	return rows
}

// Set sets the value at the given row and column, returns true if successful
func (m *Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= m.rows || col < 0 || col >= m.cols {
		return false
	}
	m.data[row][col] = val
	return true
}
