//
// This is only a SKELETON file for the 'Tournament' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const HEADER = 'Team                           | MP |  W |  D |  L |  P';

function padTeamName(name) {
  // Pad or trim team name to 31 chars (to fit 31 + 1 for the |)
  return name.padEnd(31, ' ');
}

function formatRow(team, stats) {
  return (
    padTeamName(team) +
    `|  ${stats.MP} |  ${stats.W} |  ${stats.D} |  ${stats.L} |  ${stats.P}`
  );
}

function compareTeams([teamA, statsA], [teamB, statsB]) {
  if (statsA.P !== statsB.P) {
    return statsB.P - statsA.P; // Descending by points
  }
  return teamA.localeCompare(teamB); // Alphabetical
}

export const tournamentTally = (input = '') => {
  // Map: team name -> stats object
  const teams = {};

  // Helper to ensure team exists in map
  function ensureTeam(name) {
    if (!teams[name]) {
      teams[name] = { MP: 0, W: 0, D: 0, L: 0, P: 0 };
    }
  }

  // Process each line
  input
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .forEach(line => {
      const [team1, team2, result] = line.split(';');
      if (!team1 || !team2 || !result) return; // skip malformed

      ensureTeam(team1);
      ensureTeam(team2);

      teams[team1].MP += 1;
      teams[team2].MP += 1;

      if (result === 'win') {
        teams[team1].W += 1;
        teams[team1].P += 3;
        teams[team2].L += 1;
      } else if (result === 'loss') {
        teams[team2].W += 1;
        teams[team2].P += 3;
        teams[team1].L += 1;
      } else if (result === 'draw') {
        teams[team1].D += 1;
        teams[team2].D += 1;
        teams[team1].P += 1;
        teams[team2].P += 1;
      }
    });

  // Sort teams
  const sorted = Object.entries(teams).sort(compareTeams);

  // Format output
  const lines = [HEADER];
  for (const [team, stats] of sorted) {
    lines.push(formatRow(team, stats));
  }

  return lines.join('\n');
};
