package palindrome

import (
	"errors"
	"strconv"
)

// Product type holds the palindrome value and its factor pairs.
type Product struct {
	Product int
	Factors [][2]int
}

// isPalindrome checks if a number is a palindrome.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i := 0; i < len(s)/2; i++ {
		if s[i] != s[len(s)-1-i] {
			return false
		}
	}
	return true
}

// Products finds the smallest and largest palindrome products and their factors in the given range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	palindromes := make(map[int][][2]int)
	var minPalindrome, maxPalindrome int
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if isPalindrome(product) {
				if !found || product < minPalindrome {
					minPalindrome = product
				}
				if !found || product > maxPalindrome {
					maxPalindrome = product
				}
				found = true
				palindromes[product] = append(palindromes[product], [2]int{i, j})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes found")
	}

	minProduct := Product{
		Product: minPalindrome,
		Factors: palindromes[minPalindrome],
	}
	maxProduct := Product{
		Product: maxPalindrome,
		Factors: palindromes[maxPalindrome],
	}

	return minProduct, maxProduct, nil
}
