pub mod graph {
    use std::collections::HashMap;

    #[derive(Debug, Clone)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub graph_attrs: HashMap<String, String>,
    }

    #[derive(Debug, Clone)]
    pub struct Node {
        pub id: String,
        pub attrs: HashMap<String, String>,
    }

    #[derive(Debug, Clone)]
    pub struct Edge {
        pub from: String,
        pub to: String,
        pub attrs: HashMap<String, String>,
    }

    pub struct GraphBuilder {
        nodes: Vec<Node>,
        edges: Vec<Edge>,
        graph_attrs: HashMap<String, String>,
    }

    impl GraphBuilder {
        pub fn new() -> Self {
            Self {
                nodes: Vec::new(),
                edges: Vec::new(),
                graph_attrs: HashMap::new(),
            }
        }

        pub fn node<S: Into<String>>(&mut self, id: S) -> NodeBuilder<'_> {
            NodeBuilder {
                graph_builder: self,
                id: id.into(),
                attrs: HashMap::new(),
            }
        }

        pub fn edge<S: Into<String>>(&mut self, from: S, to: S) -> EdgeBuilder<'_> {
            EdgeBuilder {
                graph_builder: self,
                from: from.into(),
                to: to.into(),
                attrs: HashMap::new(),
            }
        }

        pub fn attr<S: Into<String>>(&mut self, key: S, value: S) -> &mut Self {
            self.graph_attrs.insert(key.into(), value.into());
            self
        }

        pub fn build(self) -> Graph {
            Graph {
                nodes: self.nodes,
                edges: self.edges,
                graph_attrs: self.graph_attrs,
            }
        }
    }

    pub struct NodeBuilder<'a> {
        graph_builder: &'a mut GraphBuilder,
        id: String,
        attrs: HashMap<String, String>,
    }

    impl<'a> NodeBuilder<'a> {
        pub fn attr<S: Into<String>>(mut self, key: S, value: S) -> Self {
            self.attrs.insert(key.into(), value.into());
            self
        }

        pub fn add(self) -> &'a mut GraphBuilder {
            self.graph_builder.nodes.push(Node {
                id: self.id,
                attrs: self.attrs,
            });
            self.graph_builder
        }
    }

    pub struct EdgeBuilder<'a> {
        graph_builder: &'a mut GraphBuilder,
        from: String,
        to: String,
        attrs: HashMap<String, String>,
    }

    impl<'a> EdgeBuilder<'a> {
        pub fn attr<S: Into<String>>(mut self, key: S, value: S) -> Self {
            self.attrs.insert(key.into(), value.into());
            self
        }

        pub fn add(self) -> &'a mut GraphBuilder {
            self.graph_builder.edges.push(Edge {
                from: self.from,
                to: self.to,
                attrs: self.attrs,
            });
            self.graph_builder
        }
    }

    impl Graph {
        pub fn new() -> GraphBuilder {
            GraphBuilder::new()
        }
    }
}
