const DIGIT_WIDTH = 3;
const DIGIT_HEIGHT = 4;

// Map of OCR digit patterns to their corresponding numbers
const DIGIT_MAP = {
  // 0
  ' _ ' +
  '| |' +
  '|_|' +
  '   ': '0',
  // 1
  '   ' +
  '  |' +
  '  |' +
  '   ': '1',
  // 2
  ' _ ' +
  ' _|' +
  '|_ ' +
  '   ': '2',
  // 3
  ' _ ' +
  ' _|' +
  ' _|' +
  '   ': '3',
  // 4
  '   ' +
  '|_|' +
  '  |' +
  '   ': '4',
  // 5
  ' _ ' +
  '|_ ' +
  ' _|' +
  '   ': '5',
  // 6
  ' _ ' +
  '|_ ' +
  '|_|' +
  '   ': '6',
  // 7
  ' _ ' +
  '  |' +
  '  |' +
  '   ': '7',
  // 8
  ' _ ' +
  '|_|' +
  '|_|' +
  '   ': '8',
  // 9
  ' _ ' +
  '|_|' +
  ' _|' +
  '   ': '9',
};

function parseLines(input) {
  // Split input into lines, preserving empty lines
  return input.split('\n');
}

function validateInput(lines) {
  // All lines must be the same length
  const lineLength = lines[0].length;
  if (!lines.every(line => line.length === lineLength)) {
    throw new Error('Invalid input: lines are not the same length');
  }
  // Number of lines must be a multiple of 4
  if (lines.length % DIGIT_HEIGHT !== 0) {
    throw new Error('Invalid input: number of lines is not a multiple of 4');
  }
  // Each line's length must be a multiple of 3
  if (lineLength % DIGIT_WIDTH !== 0) {
    throw new Error('Invalid input: line length is not a multiple of 3');
  }
}

function extractDigit(lines, digitIndex) {
  // Extracts a single digit (3x4) from the given lines at the given index
  let digit = '';
  for (let i = 0; i < DIGIT_HEIGHT; i++) {
    digit += lines[i].slice(digitIndex * DIGIT_WIDTH, digitIndex * DIGIT_WIDTH + DIGIT_WIDTH);
  }
  return digit;
}

function parseOcrLine(lines) {
  // lines: array of 4 strings
  const numDigits = lines[0].length / DIGIT_WIDTH;
  let result = '';
  for (let i = 0; i < numDigits; i++) {
    const digitStr = extractDigit(lines, i);
    result += DIGIT_MAP[digitStr] || '?';
  }
  return result;
}

export const convert = (input) => {
  const lines = parseLines(input);

  // Validate input
  validateInput(lines);

  const numRows = lines.length / DIGIT_HEIGHT;
  const results = [];

  for (let row = 0; row < numRows; row++) {
    const start = row * DIGIT_HEIGHT;
    const digitLines = lines.slice(start, start + DIGIT_HEIGHT);
    results.push(parseOcrLine(digitLines));
  }

  return results.join(',');
};
