export class Board {
  constructor(inputRows) {
    // Parse the board into a 2D array
    this.board = inputRows.map(row =>
      row
        .replace(/^\s+/, '') // Remove leading spaces
        .split(' ')
        .filter(cell => cell.length > 0)
    );
    this.height = this.board.length;
    this.width = this.board[0] ? this.board[0].length : 0;
  }

  winner() {
    if (this.hasPath('O')) {
      return 'O';
    }
    if (this.hasPath('X')) {
      return 'X';
    }
    return null;
  }

  // Returns true if the player has a path from their sides
  hasPath(player) {
    const visited = Array.from({ length: this.height }, () =>
      Array(this.width).fill(false)
    );

    // For 'O', search from top row to bottom row
    if (player === 'O') {
      for (let col = 0; col < this.width; col++) {
        if (this.board[0][col] === 'O' && !visited[0][col]) {
          if (this.dfs(0, col, player, visited)) {
            return true;
          }
        }
      }
    }

    // For 'X', search from left column to right column
    if (player === 'X') {
      for (let row = 0; row < this.height; row++) {
        if (this.board[row][0] === 'X' && !visited[row][0]) {
          if (this.dfs(row, 0, player, visited)) {
            return true;
          }
        }
      }
    }

    return false;
  }

  // DFS to find a path from one side to the other
  dfs(row, col, player, visited) {
    if (
      row < 0 ||
      row >= this.height ||
      col < 0 ||
      col >= this.width ||
      visited[row][col] ||
      this.board[row][col] !== player
    ) {
      return false;
    }

    visited[row][col] = true;

    // Check if we've reached the opposite side
    if (player === 'O' && row === this.height - 1) {
      return true;
    }
    if (player === 'X' && col === this.width - 1) {
      return true;
    }

    // Hex grid neighbors (6 directions)
    const directions = [
      [-1, 0], // up
      [-1, 1], // up-right
      [0, -1], // left
      [0, 1], // right
      [1, -1], // down-left
      [1, 0], // down
    ];

    for (const [dr, dc] of directions) {
      const nr = row + dr;
      const nc = col + dc;
      if (this.dfs(nr, nc, player, visited)) {
        return true;
      }
    }

    return false;
  }
}
