    length = len(s)
    while i < length:
        if s[i] == ';':
            node, i = _parse_node(s, i + 1)
            nodes.append(node)
        elif s[i] == '(':
            # parse variation
            sub_content, j = _extract_balanced(s, i)
            sub_nodes, _ = _parse_nodes(sub_content[1:-1])
            nodes.append(sub_nodes)
            i = j
        elif s[i].isspace():
            i += 1
        else:
            # Unexpected character
            raise ValueError("tree missing")
    return nodes, ""

def _parse_node(s, i):
    properties = {}
    length = len(s)
    while i < length:
        if s[i] == ';' or s[i] == '(' or s[i] == ')':
            break
        # Parse property key
        m = re.match(r'([A-Za-z]+)', s[i:])
        if not m:
            if s[i].isspace():
                i += 1
                continue
            else:
                raise ValueError("properties without delimiter")
        key = m.group(1)
        if not key.isupper():
            raise ValueError("property must be in uppercase")
        i += len(key)
        # Parse property values
        values = []
        while i < length and s[i] == '[':
            value, i = _parse_property_value(s, i + 1)
            values.append(value)
        if not values:
            raise ValueError("properties without delimiter")
        properties[key] = values if len(values) > 1 else [values[0]]
    return properties, i

def _parse_property_value(s, i):
    value = ''
    length = len(s)
    while i < length:
        if s[i] == ']':
            i += 1
            break
        elif s[i] == '\\':
            i += 1
            if i >= length:
                break
            if s[i] == '\n':
                # Remove newline after backslash
                i += 1
            elif s[i].isspace():
                # Convert any whitespace after backslash to space
                value += ' '
                i += 1
            else:
                value += s[i]
                i += 1
        else:
            if s[i] == '\n':
                value += '\n'
            elif s[i].isspace():
                value += ' '
            else:
                value += s[i]
            i += 1
    return value, i

def _extract_balanced(s, i):
    # s[i] == '('
    depth = 0
    start = i
    length = len(s)
    while i < length:
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
            if depth == 0:
                return s[start:i+1], i+1
        i += 1
    raise ValueError("tree missing")

def _build_tree(nodes):
    # nodes is a list of dicts (properties) or lists (variations)
    if not nodes:
        raise ValueError("tree with no nodes")
    # The first node is always a dict of properties
    if not isinstance(nodes[0], dict):
        raise ValueError("tree with no nodes")
    root_properties = nodes[0]
    children = []
    i = 1
    while i < len(nodes):
        node = nodes[i]
        if isinstance(node, dict):
            # Linear child
            children.append(_build_tree([node] + nodes[i+1:]))
            break
        elif isinstance(node, list):
            # Variation
            # Each variation is a list of nodes, so pass as-is
            for variation in node:
                # If the variation is a dict, wrap in a list
                if isinstance(variation, dict):
                    children.append(_build_tree([variation]))
                else:
                    children.append(_build_tree(variation))
        i += 1
    return SgfTree(root_properties, children)
