//
// This is only a SKELETON file for the 'Queen Attack' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class QueenAttack {
  constructor({
    black: [blackRow, blackColumn] = [0, 3],
    white: [whiteRow, whiteColumn] = [7, 3],
  } = {}) {
    // Validate positions
    if (
      !QueenAttack.isValidPosition(blackRow, blackColumn) ||
      !QueenAttack.isValidPosition(whiteRow, whiteColumn)
    ) {
      throw new Error('Queen must be placed on a valid position');
    }
    if (blackRow === whiteRow && blackColumn === whiteColumn) {
      throw new Error('Queens cannot share the same space');
    }

    this.black = [blackRow, blackColumn];
    this.white = [whiteRow, whiteColumn];
  }

  static isValidPosition(row, col) {
    return (
      Number.isInteger(row) &&
      Number.isInteger(col) &&
      row >= 0 &&
      row < 8 &&
      col >= 0 &&
      col < 8
    );
  }

  toString() {
    // Create an 8x8 board filled with '_'
    const board = Array.from({ length: 8 }, () => Array(8).fill('_'));

    // Place the queens
    const [bRow, bCol] = this.black;
    const [wRow, wCol] = this.white;
    board[bRow][bCol] = 'B';
    board[wRow][wCol] = 'W';

    // Join rows into strings
    return board.map(row => row.join(' ')).join('\n');
  }

  get canAttack() {
    const [bRow, bCol] = this.black;
    const [wRow, wCol] = this.white;

    // Same row
    if (bRow === wRow) return true;
    // Same column
    if (bCol === wCol) return true;
    // Same diagonal
    if (Math.abs(bRow - wRow) === Math.abs(bCol - wCol)) return true;

    return false;
  }
}
