import java.util.*;
import java.util.stream.Collectors;

class Poker {

    private final List<String> hands;
    private final List<Hand> parsedHands;

    Poker(List<String> hands) {
        this.hands = hands;
        this.parsedHands = hands.stream().map(Hand::new).collect(Collectors.toList());
    }

    List<String> getBestHands() {
        if (parsedHands.isEmpty()) {
            return Collections.emptyList();
        }
        List<Hand> sorted = new ArrayList<>(parsedHands);
        sorted.sort(Collections.reverseOrder());
        Hand best = sorted.get(0);
        return parsedHands.stream()
                .filter(h -> h.compareTo(best) == 0)
                .map(h -> h.original)
                .collect(Collectors.toList());
    }

    private static class Hand implements Comparable<Hand> {
        private static final Map<Character, Integer> RANKS = new HashMap<>();
        static {
            char[] order = {'2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'};
            for (int i = 0; i < order.length; i++) {
                RANKS.put(order[i], i + 2);
            }
        }

        final String original;
        final List<Card> cards;
        final HandRank handRank;

        Hand(String hand) {
            this.original = hand;
            this.cards = Arrays.stream(hand.split(" "))
                    .map(Card::new)
                    .sorted(Comparator.comparingInt((Card c) -> c.rank).reversed())
                    .collect(Collectors.toList());
            this.handRank = evaluate();
        }

        private HandRank evaluate() {
            boolean flush = isFlush();
            boolean straight = isStraight();
            Map<Integer, Long> rankCounts = cards.stream()
                    .collect(Collectors.groupingBy(c -> c.rank, Collectors.counting()));
            List<Map.Entry<Integer, Long>> groups = rankCounts.entrySet().stream()
                    .sorted((a, b) -> {
                        int cmp = Long.compare(b.getValue(), a.getValue());
                        if (cmp != 0) return cmp;
                        return Integer.compare(b.getKey(), a.getKey());
                    })
                    .collect(Collectors.toList());

            List<Integer> groupRanks = groups.stream().map(Map.Entry::getKey).collect(Collectors.toList());
            List<Long> groupCounts = groups.stream().map(Map.Entry::getValue).collect(Collectors.toList());

            if (straight && flush) {
                return new HandRank(HandType.STRAIGHT_FLUSH, getStraightHighCard(), Collections.emptyList());
            }
            if (groupCounts.get(0) == 4) {
                return new HandRank(HandType.FOUR_OF_A_KIND, groupRanks.get(0), Arrays.asList(groupRanks.get(1)));
            }
            if (groupCounts.get(0) == 3 && groupCounts.get(1) == 2) {
                return new HandRank(HandType.FULL_HOUSE, groupRanks.get(0), Arrays.asList(groupRanks.get(1)));
            }
            if (flush) {
                return new HandRank(HandType.FLUSH, getRanks(), Collections.emptyList());
            }
            if (straight) {
                return new HandRank(HandType.STRAIGHT, getStraightHighCard(), Collections.emptyList());
            }
            if (groupCounts.get(0) == 3) {
                return new HandRank(HandType.THREE_OF_A_KIND, groupRanks.get(0), groupRanks.subList(1, groupRanks.size()));
            }
            if (groupCounts.get(0) == 2 && groupCounts.get(1) == 2) {
                List<Integer> kickers = new ArrayList<>();
                kickers.add(groupRanks.get(0));
                kickers.add(groupRanks.get(1));
                kickers.add(groupRanks.get(2));
                return new HandRank(HandType.TWO_PAIR, groupRanks.get(0), kickers);
            }
            if (groupCounts.get(0) == 2) {
                List<Integer> kickers = new ArrayList<>();
                kickers.add(groupRanks.get(0));
                kickers.addAll(groupRanks.subList(1, groupRanks.size()));
                return new HandRank(HandType.ONE_PAIR, groupRanks.get(0), kickers);
            }
            return new HandRank(HandType.HIGH_CARD, getRanks(), Collections.emptyList());
        }

        private boolean isFlush() {
            char suit = cards.get(0).suit;
            for (Card c : cards) {
                if (c.suit != suit) return false;
            }
            return true;
        }

        private boolean isStraight() {
            List<Integer> ranks = getRanks();
            for (int i = 1; i < ranks.size(); i++) {
                if (ranks.get(i) != ranks.get(i - 1) - 1) {
                    // Special case: 5-4-3-2-A
                    if (i == 1 && ranks.get(0) == 14 && ranks.get(1) == 5) {
                        // Check for 5-4-3-2-A
                        for (int j = 1; j < ranks.size() - 1; j++) {
                            if (ranks.get(j) != ranks.get(j + 1) + 1) return false;
                        }
                        return ranks.get(4) == 2;
                    }
                    return false;
                }
            }
            return true;
        }

        private int getStraightHighCard() {
            List<Integer> ranks = getRanks();
            // Special case: 5-4-3-2-A
            if (ranks.get(0) == 14 && ranks.get(1) == 5) {
                return 5;
            }
            return ranks.get(0);
        }

        private List<Integer> getRanks() {
            return cards.stream().map(c -> c.rank).collect(Collectors.toList());
        }

        @Override
        public int compareTo(Hand o) {
            return this.handRank.compareTo(o.handRank);
        }
    }

    private static class Card {
        final int rank;
        final char suit;

        Card(String s) {
            this.rank = Hand.RANKS.get(s.charAt(0));
            this.suit = s.charAt(1);
        }
    }

    private static class HandRank implements Comparable<HandRank> {
        final HandType type;
        final List<Integer> ranks;
        final List<Integer> kickers;

        // For hands where a single high card is relevant (straight, straight flush, etc)
        HandRank(HandType type, int high, List<Integer> kickers) {
            this.type = type;
            this.ranks = Collections.singletonList(high);
            this.kickers = new ArrayList<>(kickers);
        }

        // For hands where all cards are relevant (flush, high card)
        HandRank(HandType type, List<Integer> ranks, List<Integer> kickers) {
            this.type = type;
            this.ranks = new ArrayList<>(ranks);
            this.kickers = new ArrayList<>(kickers);
        }

        @Override
        public int compareTo(HandRank o) {
            int cmp = Integer.compare(this.type.rank, o.type.rank);
            if (cmp != 0) return cmp;
            for (int i = 0; i < Math.min(this.ranks.size(), o.ranks.size()); i++) {
                cmp = Integer.compare(this.ranks.get(i), o.ranks.get(i));
                if (cmp != 0) return cmp;
            }
            for (int i = 0; i < Math.min(this.kickers.size(), o.kickers.size()); i++) {
                cmp = Integer.compare(this.kickers.get(i), o.kickers.get(i));
                if (cmp != 0) return cmp;
            }
            return 0;
        }
    }

    private enum HandType {
        HIGH_CARD(1),
        ONE_PAIR(2),
        TWO_PAIR(3),
        THREE_OF_A_KIND(4),
        STRAIGHT(5),
        FLUSH(6),
        FULL_HOUSE(7),
        FOUR_OF_A_KIND(8),
        STRAIGHT_FLUSH(9);

        final int rank;
        HandType(int rank) {
            this.rank = rank;
        }
    }
}
