import java.util.*;

class ForthEvaluator {
    private static final Set<String> BUILTINS = new HashSet<>(Arrays.asList(
        "+", "-", "*", "/", "dup", "drop", "swap", "over"
    ));

    private final Map<String, List<String>> userWords = new HashMap<>();

    List<Integer> evaluateProgram(List<String> input) {
        List<Integer> stack = new ArrayList<>();
        Map<String, List<String>> words = new HashMap<>(userWords);

        List<String> tokens = new ArrayList<>();
        for (String line : input) {
            tokens.addAll(tokenize(line));
        }

        Deque<String> tokenStream = new ArrayDeque<>(tokens);

        while (!tokenStream.isEmpty()) {
            String token = tokenStream.pollFirst();
            if (token.equals(":")) {
                // Start of word definition
                if (tokenStream.isEmpty()) {
                    throw new IllegalArgumentException("No word name after ':'");
                }
                String wordName = tokenStream.pollFirst().toLowerCase();
                if (isNumber(wordName)) {
                    throw new IllegalArgumentException("Cannot redefine numbers");
                }
                List<String> definition = new ArrayList<>();
                while (!tokenStream.isEmpty()) {
                    String defToken = tokenStream.pollFirst();
                    if (defToken.equals(";")) {
                        break;
                    }
                    definition.add(defToken);
                }
                if (definition.isEmpty() || !definition.get(definition.size() - 1).equals(";")) {
                    // If we didn't find a ';', error
                    if (definition.isEmpty() || !";".equals(definition.get(definition.size() - 1))) {
                        throw new IllegalArgumentException("Missing ';' in definition");
                    }
                }
                // Remove trailing ';' if present
                if (!definition.isEmpty() && definition.get(definition.size() - 1).equals(";")) {
                    definition.remove(definition.size() - 1);
                }
                words.put(wordName, toLowerCase(definition));
            } else {
                evalToken(token, stack, words, tokenStream);
            }
        }
        return stack;
    }

    private void evalToken(String token, List<Integer> stack, Map<String, List<String>> words, Deque<String> tokenStream) {
        String t = token.toLowerCase();
        if (isNumber(t)) {
            stack.add(Integer.parseInt(t));
        } else if (BUILTINS.contains(t)) {
            evalBuiltin(t, stack);
        } else if (words.containsKey(t)) {
            // Expand user-defined word
            List<String> definition = words.get(t);
            // Insert definition tokens at the front of the tokenStream
            ListIterator<String> it = definition.listIterator(definition.size());
            while (it.hasPrevious()) {
                tokenStream.addFirst(it.previous());
            }
        } else {
            throw new IllegalArgumentException("Unknown word: " + token);
        }
    }

    private void evalBuiltin(String word, List<Integer> stack) {
        switch (word) {
            case "+":
                requireStack(stack, 2, "+");
                stack.add(stack.remove(stack.size() - 2) + stack.remove(stack.size() - 1));
                break;
            case "-":
                requireStack(stack, 2, "-");
                stack.add(stack.remove(stack.size() - 2) - stack.remove(stack.size() - 1));
                break;
            case "*":
                requireStack(stack, 2, "*");
                stack.add(stack.remove(stack.size() - 2) * stack.remove(stack.size() - 1));
                break;
            case "/":
                requireStack(stack, 2, "/");
                int divisor = stack.remove(stack.size() - 1);
                int dividend = stack.remove(stack.size() - 1);
                if (divisor == 0) {
                    throw new ArithmeticException("Division by zero");
                }
                stack.add(dividend / divisor);
                break;
            case "dup":
                requireStack(stack, 1, "DUP");
                stack.add(stack.get(stack.size() - 1));
                break;
            case "drop":
                requireStack(stack, 1, "DROP");
                stack.remove(stack.size() - 1);
                break;
            case "swap":
                requireStack(stack, 2, "SWAP");
                int a = stack.remove(stack.size() - 1);
                int b = stack.remove(stack.size() - 1);
                stack.add(a);
                stack.add(b);
                break;
            case "over":
                requireStack(stack, 2, "OVER");
                stack.add(stack.get(stack.size() - 2));
                break;
            default:
                throw new IllegalArgumentException("Unknown builtin: " + word);
        }
    }

    private void requireStack(List<Integer> stack, int n, String op) {
        if (stack.size() < n) {
            throw new IllegalArgumentException("Stack underflow for operation: " + op);
        }
    }

    private boolean isNumber(String s) {
        if (s.isEmpty()) return false;
        int i = 0;
        if (s.charAt(0) == '-' && s.length() > 1) i = 1;
        for (; i < s.length(); i++) {
            if (!Character.isDigit(s.charAt(i))) return false;
        }
        return true;
    }

    private List<String> tokenize(String line) {
        // Split by whitespace, preserve punctuation as part of words
        String[] parts = line.trim().split("\\s+");
        List<String> tokens = new ArrayList<>();
        for (String part : parts) {
            if (!part.isEmpty()) {
                tokens.add(part);
            }
        }
        return tokens;
    }

    private List<String> toLowerCase(List<String> tokens) {
        List<String> out = new ArrayList<>(tokens.size());
        for (String t : tokens) {
            out.add(t.toLowerCase());
        }
        return out;
    }
}
