import java.util.Objects;

class Rational {

    private final int numerator;
    private final int denominator;

    Rational(int numerator, int denominator) {
        if (denominator == 0) {
            throw new ArithmeticException("Denominator cannot be zero.");
        }
        // Reduce to lowest terms and ensure denominator is positive
        int gcd = gcd(Math.abs(numerator), Math.abs(denominator));
        int num = numerator / gcd;
        int denom = denominator / gcd;
        // Ensure denominator is positive
        if (denom < 0) {
            num = -num;
            denom = -denom;
        }
        this.numerator = num;
        this.denominator = denom;
    }

    int getNumerator() {
        return numerator;
    }

    int getDenominator() {
        return denominator;
    }

    Rational add(Rational other) {
        int num = this.numerator * other.denominator + other.numerator * this.denominator;
        int denom = this.denominator * other.denominator;
        return new Rational(num, denom);
    }

    Rational subtract(Rational other) {
        int num = this.numerator * other.denominator - other.numerator * this.denominator;
        int denom = this.denominator * other.denominator;
        return new Rational(num, denom);
    }

    Rational multiply(Rational other) {
        int num = this.numerator * other.numerator;
        int denom = this.denominator * other.denominator;
        return new Rational(num, denom);
    }

    Rational divide(Rational other) {
        if (other.numerator == 0) {
            throw new ArithmeticException("Cannot divide by zero.");
        }
        int num = this.numerator * other.denominator;
        int denom = this.denominator * other.numerator;
        return new Rational(num, denom);
    }

    Rational abs() {
        return new Rational(Math.abs(this.numerator), Math.abs(this.denominator));
    }

    Rational pow(int power) {
        if (power == 0) {
            return new Rational(1, 1);
        } else if (power > 0) {
            return new Rational((int) Math.pow(this.numerator, power), (int) Math.pow(this.denominator, power));
        } else {
            int absPower = Math.abs(power);
            return new Rational((int) Math.pow(this.denominator, absPower), (int) Math.pow(this.numerator, absPower));
        }
    }

    double exp(double exponent) {
        // (a/b)^x = a^x / b^x
        return Math.pow(this.numerator, exponent) / Math.pow(this.denominator, exponent);
    }

    // Helper: greatest common divisor
    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    // Static method for real number to rational exponentiation: x^(a/b)
    static double exp(double base, Rational exponent) {
        // x^(a/b) = root(x^a, b)
        return Math.pow(base, (double) exponent.numerator / exponent.denominator);
    }

    @Override
    public String toString() {
        return String.format("%d/%d", this.getNumerator(), this.getDenominator());
    }

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof Rational other) {
            return this.getNumerator() == other.getNumerator()
                    && this.getDenominator() == other.getDenominator();
        }

        return false;
    }

    @Override
    public int hashCode() {
        return Objects.hash(this.getNumerator(), this.getDenominator());
    }
}
