const BOOK_PRICE = 800;
const DISCOUNTS = {
  1: 1.0,
  2: 0.95,
  3: 0.90,
  4: 0.80,
  5: 0.75,
};

function getBookCounts(books) {
  // Count how many of each book we have
  const counts = [0, 0, 0, 0, 0];
  for (const book of books) {
    counts[book - 1]++;
  }
  return counts;
}

function minCost(counts, memo = {}) {
  // Memoization key
  const key = counts.join(',');
  if (memo[key] !== undefined) {
    return memo[key];
  }

  // If all counts are zero, cost is zero
  if (counts.every(c => c === 0)) {
    return 0;
  }

  let min = Infinity;

  // Try all possible groupings (from 5 down to 1)
  for (let groupSize = 5; groupSize >= 1; groupSize--) {
    // Find all indices with at least one book
    let idxs = [];
    for (let i = 0; i < counts.length; i++) {
      if (counts[i] > 0) {
        idxs.push(i);
      }
    }
    if (idxs.length < groupSize) continue;

    // Generate all combinations of groupSize indices
    function combinations(arr, k) {
      if (k === 0) return [[]];
      if (arr.length < k) return [];
      let result = [];
      for (let i = 0; i <= arr.length - k; i++) {
        let head = arr[i];
        let tailcombs = combinations(arr.slice(i + 1), k - 1);
        for (let tail of tailcombs) {
          result.push([head, ...tail]);
        }
      }
      return result;
    }

    let combs = combinations(idxs, groupSize);
    for (const comb of combs) {
      const newCounts = counts.slice();
      for (const idx of comb) {
        newCounts[idx]--;
      }
      const groupCost = Math.round(groupSize * BOOK_PRICE * DISCOUNTS[groupSize]);
      const totalCost = groupCost + minCost(newCounts, memo);
      if (totalCost < min) {
        min = totalCost;
      }
    }
  }

  memo[key] = min;
  return min;
}

export const cost = (books) => {
  const counts = getBookCounts(books);
  return minCost(counts);
};
