func permute(arr []string) [][]string {
	var helper func([]string, int)
	res := [][]string{}

	helper = func(a []string, n int) {
		if n == 1 {
			tmp := make([]string, len(a))
			copy(tmp, a)
			res = append(res, tmp)
		} else {
			for i := 0; i < n; i++ {
				helper(a, n-1)
				if n%2 == 1 {
					a[0], a[n-1] = a[n-1], a[0]
				} else {
					a[i], a[n-1] = a[n-1], a[i]
				}
			}
		}
	}
	helper(arr, len(arr))
	return res
}

