enum GameState {
    ONGOING,
    DRAW,
    WIN
}

class StateOfTicTacToe {
    public GameState determineState(String[] board) {
        if (board == null || board.length != 9) {
            throw new IllegalArgumentException("Board must be a String array of length 9.");
        }

        // Validate board characters and count Xs and Os
        int xCount = 0;
        int oCount = 0;
        for (String cell : board) {
            if (cell == null || (!cell.equals("X") && !cell.equals("O") && !cell.equals(" "))) {
                throw new IllegalArgumentException("Board can only contain 'X', 'O', or ' ' (space).");
            }
            if (cell.equals("X")) xCount++;
            if (cell.equals("O")) oCount++;
        }

        // X always goes first, so xCount >= oCount and xCount - oCount <= 1
        if (oCount > xCount || xCount - oCount > 1) {
            throw new IllegalArgumentException("Invalid number of Xs and Os.");
        }

        // Check for winners
        int[][] winPatterns = {
            {0,1,2}, {3,4,5}, {6,7,8}, // rows
            {0,3,6}, {1,4,7}, {2,5,8}, // columns
            {0,4,8}, {2,4,6}           // diagonals
        };

        boolean xWins = false;
        boolean oWins = false;
        for (int[] pattern : winPatterns) {
            String a = board[pattern[0]];
            String b = board[pattern[1]];
            String c = board[pattern[2]];
            if (a.equals("X") && b.equals("X") && c.equals("X")) xWins = true;
            if (a.equals("O") && b.equals("O") && c.equals("O")) oWins = true;
        }

        // Both players cannot win
        if (xWins && oWins) {
            throw new IllegalArgumentException("Both players cannot win.");
        }

        // If X wins, X must have one more than O
        if (xWins && xCount != oCount + 1) {
            throw new IllegalArgumentException("Invalid board: X wins but does not have one more move than O.");
        }

        // If O wins, X and O must have same count
        if (oWins && xCount != oCount) {
            throw new IllegalArgumentException("Invalid board: O wins but does not have same number of moves as X.");
        }

        // If someone has won, the game must not continue (no more moves after win)
        if (xWins || oWins) {
            // Check if there are moves after the win
            // To do this, we can simulate the game and see if the win could have happened at the last move
            // But for simplicity, if there is a win, and the board is not full, it's still valid as long as the move counts are correct
            return GameState.WIN;
        }

        // If board is full and no winner, it's a draw
        if (xCount + oCount == 9) {
            return GameState.DRAW;
        }

        // Otherwise, game is ongoing
        return GameState.ONGOING;
    }
}
