#if !defined(BINARY_SEARCH_TREE_H)
#define BINARY_SEARCH_TREE_H

#include <memory>
#include <iterator>
#include <vector>
#include <stack>
#include <utility>

namespace binary_search_tree {

template <typename T>
class binary_tree {
public:
    // Type aliases for unique_ptr and value_type
    using value_type = T;
    using tree_ptr = std::unique_ptr<binary_tree<T>>;

    // Constructors
    explicit binary_tree(const T& value) : data_(value) {}

    // Insert value into the tree
    void insert(const T& value) {
        if (value <= data_) {
            if (left_) {
                left_->insert(value);
            } else {
                left_ = std::make_unique<binary_tree<T>>(value);
            }
        } else {
            if (right_) {
                right_->insert(value);
            } else {
                right_ = std::make_unique<binary_tree<T>>(value);
            }
        }
    }

    // Accessors
    const T& data() const { return data_; }
    const tree_ptr& left() const { return left_; }
    const tree_ptr& right() const { return right_; }

    // In-order iterator
    class iterator {
    public:
        using value_type = T;
        using reference = const T&;
        using pointer = const T*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::forward_iterator_tag;

        iterator() = default;

        explicit iterator(const binary_tree<T>* root) {
            push_left(root);
        }

        reference operator*() const {
            return node_stack_.top()->data_;
        }

        pointer operator->() const {
            return &(node_stack_.top()->data_);
        }

        iterator& operator++() {
            const binary_tree<T>* node = node_stack_.top();
            node_stack_.pop();
            if (node->right_) {
                push_left(node->right_.get());
            }
            return *this;
        }

        iterator operator++(int) {
            iterator tmp = *this;
            ++(*this);
            return tmp;
        }

        bool operator==(const iterator& other) const {
            if (node_stack_.empty() && other.node_stack_.empty()) return true;
            if (node_stack_.empty() || other.node_stack_.empty()) return false;
            return node_stack_.top() == other.node_stack_.top();
        }

        bool operator!=(const iterator& other) const {
            return !(*this == other);
        }

    private:
        std::stack<const binary_tree<T>*> node_stack_;

        void push_left(const binary_tree<T>* node) {
            while (node) {
                node_stack_.push(node);
                node = node->left_ ? node->left_.get() : nullptr;
            }
        }
    };

    iterator begin() const { return iterator(this); }
    iterator end() const { return iterator(); }

private:
    T data_;
    tree_ptr left_{nullptr};
    tree_ptr right_{nullptr};
};

// Helper function to build a tree from a vector
template <typename T>
std::unique_ptr<binary_tree<T>> make_tree(const std::vector<T>& data) {
    if (data.empty()) return nullptr;
    auto root = std::make_unique<binary_tree<T>>(data[0]);
    for (size_t i = 1; i < data.size(); ++i) {
        root->insert(data[i]);
    }
    return root;
}

}  // namespace binary_search_tree

#endif // BINARY_SEARCH_TREE_H
