// This is only a SKELETON file for the 'Scale Generator' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const SHARP_SCALE = [
  'A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#'
];

const FLAT_SCALE = [
  'A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab'
];

// Tonics that use the flat scale
const FLAT_TONICS = [
  'F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb',
  'd', 'g', 'c', 'f', 'bb', 'eb'
];

// Tonics that use the sharp scale
const SHARP_TONICS = [
  'C', 'G', 'D', 'A', 'E', 'B', 'F#',
  'a', 'e', 'b', 'f#', 'c#', 'g#', 'd#'
];

// Always use sharps for C and a (per instructions)
const SPECIAL_SHARP_TONICS = ['C', 'a'];

function normalizeTonic(tonic) {
  if (tonic.length === 1) {
    return tonic.toUpperCase();
  }
  // e.g. 'f#', 'bb', 'eb'
  return tonic[0].toUpperCase() + tonic.slice(1).replace('♯', '#').replace('♭', 'b');
}

function getScaleType(tonic) {
  // Return 'sharp' or 'flat'
  const norm = normalizeTonic(tonic);
  if (SPECIAL_SHARP_TONICS.includes(norm)) {
    return 'sharp';
  }
  if (FLAT_TONICS.includes(tonic.toLowerCase())) {
    return 'flat';
  }
  return 'sharp';
}

function getScaleArray(tonic) {
  return getScaleType(tonic) === 'flat' ? FLAT_SCALE : SHARP_SCALE;
}

function capitalizeNote(note) {
  // Capitalize the letter, keep accidental as is
  if (note.length === 1) return note.toUpperCase();
  return note[0].toUpperCase() + note.slice(1);
}

function rotateScale(scale, tonic) {
  // Find the index of the tonic in the scale and rotate
  // Accept both 'Db' and 'D♭' as input
  let normTonic = tonic.replace('♯', '#').replace('♭', 'b');
  normTonic = capitalizeNote(normTonic);
  // Try to find the tonic in the scale
  let idx = scale.findIndex(n => n.toUpperCase() === normTonic.toUpperCase());
  if (idx === -1) {
    // Try enharmonic equivalents (e.g. Db <-> C#)
    if (normTonic.length === 2) {
      if (normTonic[1] === 'b') {
        // Try sharp equivalent
        const sharpEquivalent = getSharpEquivalent(normTonic);
        idx = scale.findIndex(n => n.toUpperCase() === sharpEquivalent.toUpperCase());
      } else if (normTonic[1] === '#') {
        // Try flat equivalent
        const flatEquivalent = getFlatEquivalent(normTonic);
        idx = scale.findIndex(n => n.toUpperCase() === flatEquivalent.toUpperCase());
      }
    }
  }
  if (idx === -1) {
    throw new Error(`Tonic ${tonic} not found in scale`);
  }
  return [...scale.slice(idx), ...scale.slice(0, idx)];
}

// Map flats to sharps and vice versa for enharmonic equivalents
function getSharpEquivalent(flatNote) {
  // e.g. Db -> C#
  const flatToSharp = {
    'Bb': 'A#',
    'Db': 'C#',
    'Eb': 'D#',
    'Gb': 'F#',
    'Ab': 'G#'
  };
  return flatToSharp[flatNote] || flatNote;
}

function getFlatEquivalent(sharpNote) {
  // e.g. C# -> Db
  const sharpToFlat = {
    'A#': 'Bb',
    'C#': 'Db',
    'D#': 'Eb',
    'F#': 'Gb',
    'G#': 'Ab'
  };
  return sharpToFlat[sharpNote] || sharpNote;
}

export class Scale {
  constructor(tonic) {
    this.tonic = tonic;
    this.scaleType = getScaleType(tonic);
    this.scaleArray = getScaleArray(tonic);
    this.chromaticScale = rotateScale(this.scaleArray, tonic);
  }

  chromatic() {
    // Return all 12 notes, starting from tonic, in correct accidental form
    return this.chromaticScale.map(capitalizeNote);
  }

  interval(intervals) {
    // intervals: string like 'MMmMMMm'
    let notes = [];
    let idx = 0;
    notes.push(capitalizeNote(this.chromaticScale[idx]));
    for (let i = 0; i < intervals.length; i++) {
      const step = intervals[i];
      if (step === 'm') {
        idx += 1;
      } else if (step === 'M') {
        idx += 2;
      } else if (step === 'A') {
        idx += 3;
      } else {
        throw new Error(`Unknown interval: ${step}`);
      }
      // Wrap around if needed
      idx = idx % this.chromaticScale.length;
      notes.push(capitalizeNote(this.chromaticScale[idx]));
    }
    return notes;
  }
}
