//
// This is only a SKELETON file for the 'Bowling' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class Bowling {
  constructor() {
    this.rolls = [];
  }

  roll(pins) {
    if (pins < 0 || pins > 10) {
      throw new Error('Invalid number of pins');
    }
    this.rolls.push(pins);
  }

  score() {
    let score = 0;
    let rollIndex = 0;
    let frames = 0;

    while (frames < 10) {
      if (this.isStrike(rollIndex)) {
        // Strike
        score += 10 + this.strikeBonus(rollIndex);
        rollIndex += 1;
      } else if (this.isSpare(rollIndex)) {
        // Spare
        score += 10 + this.spareBonus(rollIndex);
        rollIndex += 2;
      } else {
        // Open frame
        score += this.sumOfBallsInFrame(rollIndex);
        rollIndex += 2;
      }
      frames++;
    }

    // Validate that the game is complete (no extra rolls except for fill balls in 10th frame)
    if (rollIndex < this.rolls.length) {
      // There may be extra fill balls, but only allowed in 10th frame
      // Check if the extra balls are valid
      const extra = this.rolls.length - rollIndex;
      const tenthFirst = this.rolls[this.getTenthFrameFirstRollIndex()];
      const tenthSecond = this.rolls[this.getTenthFrameFirstRollIndex() + 1];
      if (
        (tenthFirst === 10 && extra > 2) || // Strike in 10th, max 2 fill balls
        (tenthFirst + tenthSecond === 10 && tenthFirst !== 10 && extra > 1) || // Spare in 10th, max 1 fill ball
        (tenthFirst + tenthSecond < 10 && extra > 0) // Open frame, no fill balls
      ) {
        throw new Error('Cannot roll after game is over');
      }
    }

    return score;
  }

  isStrike(rollIndex) {
    return this.rolls[rollIndex] === 10;
  }

  isSpare(rollIndex) {
    return (
      this.rolls[rollIndex] + this.rolls[rollIndex + 1] === 10
    );
  }

  strikeBonus(rollIndex) {
    return (
      (this.rolls[rollIndex + 1] || 0) +
      (this.rolls[rollIndex + 2] || 0)
    );
  }

  spareBonus(rollIndex) {
    return this.rolls[rollIndex + 2] || 0;
  }

  sumOfBallsInFrame(rollIndex) {
    return (
      (this.rolls[rollIndex] || 0) +
      (this.rolls[rollIndex + 1] || 0)
    );
  }

  getTenthFrameFirstRollIndex() {
    let rollIndex = 0;
    let frames = 0;
    while (frames < 9) {
      if (this.isStrike(rollIndex)) {
        rollIndex += 1;
      } else {
        rollIndex += 2;
      }
      frames++;
    }
    return rollIndex;
  }
}
