class LedgerEntry {
  constructor() {
    this.date = undefined;
    this.description = undefined;
    this.change = undefined;
  }
}

export function createEntry(date, description, change) {
  let entry = new LedgerEntry();
  entry.date = new Date(date);
  entry.description = description;
  entry.change = change;
  return entry;
}

// --- Refactoring log ---
// 1. Extracted locale/currency formatting data to a config object for clarity and maintainability.
// 2. Extracted sorting logic to a helper function.
// 3. Extracted row formatting to helper functions per locale.
// 4. Removed duplicate code by using config and helpers.
// 5. Used consistent variable naming and removed unnecessary code duplication.

const LOCALE_CONFIG = {
  'en-US': {
    header: [
      { label: 'Date', width: 10 },
      { label: 'Description', width: 25 },
      { label: 'Change', width: 13 },
    ],
    dateFormat: (date) =>
      `${(date.getMonth() + 1).toString().padStart(2, '0')}/${date
        .getDate()
        .toString()
        .padStart(2, '0')}/${date.getFullYear()}`,
    currencyFormat: (amount, currency) => {
      const options = {
        style: 'currency',
        currency,
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      };
      if (amount < 0) {
        // Accounting format: negative numbers in parentheses
        return (
          '(' +
          Math.abs(amount / 100).toLocaleString('en-US', options) +
          ')'
        ).padStart(13, ' ');
      } else {
        return (
          (amount / 100).toLocaleString('en-US', options) + ' '
        ).padStart(13, ' ');
      }
    },
    descriptionFormat: (desc) =>
      desc.length > 25
        ? desc.substring(0, 22) + '...'
        : desc.padEnd(25, ' '),
    separator: ' | ',
  },
  'nl-NL': {
    header: [
      { label: 'Datum', width: 10 },
      { label: 'Omschrijving', width: 25 },
      { label: 'Verandering', width: 13 },
    ],
    dateFormat: (date) =>
      `${date.getDate().toString().padStart(2, '0')}-${(date.getMonth() + 1)
        .toString()
        .padStart(2, '0')}-${date.getFullYear()}`,
    currencyFormat: (amount, currency) => {
      const options = {
        style: 'currency',
        currency,
        currencyDisplay: 'narrowSymbol',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      };
      return (
        (amount / 100).toLocaleString('nl-NL', options) + ' '
      ).padStart(13, ' ');
    },
    descriptionFormat: (desc) =>
      desc.length > 25
        ? desc.substring(0, 22) + '...'
        : desc.padEnd(25, ' '),
    separator: ' | ',
  },
};

function sortEntries(entries) {
  entries.sort(
    (a, b) =>
      a.date - b.date ||
      a.change - b.change ||
      a.description.localeCompare(b.description),
  );
}

function formatHeader(locale) {
  const config = LOCALE_CONFIG[locale];
  return (
    config.header
      .map((col) => col.label.padEnd(col.width, ' '))
      .join(config.separator) + '\n'
  );
}

function formatRow(entry, currency, locale) {
  const config = LOCALE_CONFIG[locale];
  return (
    config.dateFormat(entry.date).padEnd(10, ' ') +
    config.separator +
    config.descriptionFormat(entry.description) +
    config.separator +
    config.currencyFormat(entry.change, currency) +
    '\n'
  );
}

export function formatEntries(currency, locale, entries) {
  if (!LOCALE_CONFIG[locale]) {
    throw new Error(`Unsupported locale: ${locale}`);
  }
  let table = '';
  table += formatHeader(locale);

  // Sort entries
  sortEntries(entries);

  // Format each entry
  entries.forEach((entry) => {
    table += formatRow(entry, currency, locale);
  });

  // Remove trailing newline
  return table.replace(/\n$/, '');
}
