    std::string color;
    std::string nationality;
    std::string pet;
    std::string drink;
    std::string hobby;
};

bool is_next_to(int a, int b) {
    return std::abs(a - b) == 1;
}

bool is_right_of(int a, int b) {
    return a - b == 1;
}

} // namespace

Solution solve() {
