        int ivory = std::find(color.begin(), color.end(), 2) - color.begin(); // ivory
        if (!is_right_of(green, ivory)) continue;

        for (const auto& nat : nat_perms) {
            // 2. The Englishman lives in the red house.
            int englishman = std::find(nat.begin(), nat.end(), 0) - nat.begin(); // Englishman
            int red = std::find(color.begin(), color.end(), 0) - color.begin(); // red
            if (englishman != red) continue;

            // 10. The Norwegian lives in the first house.
            int norwegian = std::find(nat.begin(), nat.end(), 3) - nat.begin(); // Norwegian
            if (norwegian != 0) continue;

            // 15. The Norwegian lives next to the blue house.
            int blue = std::find(color.begin(), color.end(), 4) - color.begin(); // blue
            if (!is_next_to(norwegian, blue)) continue;

            for (const auto& pet : pet_perms) {
                // 3. The Spaniard owns the dog.
                int spaniard = std::find(nat.begin(), nat.end(), 1) - nat.begin(); // Spaniard
                int dog = std::find(pet.begin(), pet.end(), 0) - pet.begin(); // dog
                if (spaniard != dog) continue;

                for (const auto& drink : drink_perms) {
                    // 4. The person in the green house drinks coffee.
                    int coffee = std::find(drink.begin(), drink.end(), 0) - drink.begin(); // coffee
                    if (green != coffee) continue;

                    // 5. The Ukrainian drinks tea.
                    int ukrainian = std::find(nat.begin(), nat.end(), 2) - nat.begin(); // Ukrainian
                    int tea = std::find(drink.begin(), drink.end(), 1) - drink.begin(); // tea
                    if (ukrainian != tea) continue;

                    // 9. The person in the middle house drinks milk.
                    int milk = std::find(drink.begin(), drink.end(), 2) - drink.begin(); // milk
                    if (milk != 2) continue;

                    for (const auto& hobby : hobby_perms) {
                        // 7. The snail owner likes to go dancing.
                        int snails = std::find(pet.begin(), pet.end(), 1) - pet.begin(); // snails
                        int dancing = std::find(hobby.begin(), hobby.end(), 0) - hobby.begin(); // dancing
                        if (snails != dancing) continue;

                        // 8. The person in the yellow house is a painter.
                        int yellow = std::find(color.begin(), color.end(), 3) - color.begin(); // yellow
                        int painting = std::find(hobby.begin(), hobby.end(), 2) - hobby.begin(); // painting
                        if (yellow != painting) continue;

                        // 12. The painter's house is next to the house with the horse.
                        int horse = std::find(pet.begin(), pet.end(), 3) - pet.begin(); // horse
                        if (!is_next_to(painting, horse)) continue;

                        // 13. The person who plays football drinks orange juice.
                        int football = std::find(hobby.begin(), hobby.end(), 4) - hobby.begin(); // football
                        int orange_juice = std::find(drink.begin(), drink.end(), 3) - drink.begin(); // orange juice
                        if (football != orange_juice) continue;

                        // 14. The Japanese person plays chess.
                        int japanese = std::find(nat.begin(), nat.end(), 4) - nat.begin(); // Japanese
                        int chess = std::find(hobby.begin(), hobby.end(), 3) - hobby.begin(); // chess
                        if (japanese != chess) continue;

                        // 11. The person who enjoys reading lives in the house next to the person with the fox.
                        int reading = std::find(hobby.begin(), hobby.end(), 1) - hobby.begin(); // reading
                        int fox = std::find(pet.begin(), pet.end(), 2) - pet.begin(); // fox
                        if (!is_next_to(reading, fox)) continue;

                        // All constraints satisfied, build the solution
                        std::array<House, N> houses;
                        for (int i = 0; i < N; ++i) {
                            houses[i] = House{
                                colors[color[i]],
                                nationalities[nat[i]],
                                pets[pet[i]],
                                drinks[drink[i]],
                                hobbies[hobby[i]]
                            };
                        }

                        // Find who drinks water and who owns the zebra
                        std::string drinksWater, ownsZebra;
                        for (const auto& h : houses) {
                            if (h.drink == "water") drinksWater = h.nationality;
                            if (h.pet == "zebra") ownsZebra = h.nationality;
                        }
                        return Solution{drinksWater, ownsZebra};
                    }
                }
            }
        }
    }
    // If no solution found
    return Solution{"", ""};
}

}  // namespace zebra_puzzle
