class ResistorColorTrio {
    private static final String[] COLORS = {
        "black", "brown", "red", "orange", "yellow",
        "green", "blue", "violet", "grey", "white"
    };

    String label(String[] colors) {
        int firstDigit = colorValue(colors[0]);
        int secondDigit = colorValue(colors[1]);
        int multiplier = colorValue(colors[2]);

        int value = (firstDigit * 10 + secondDigit) * (int)Math.pow(10, multiplier);

        String label;
        if (value >= 1_000_000) {
            if (value % 1_000_000 == 0) {
                label = (value / 1_000_000) + " megaohms";
            } else {
                label = (value / 1_000_000.0) + " megaohms";
            }
        } else if (value >= 1_000) {
            if (value % 1_000 == 0) {
                label = (value / 1_000) + " kiloohms";
            } else {
                label = (value / 1_000.0) + " kiloohms";
            }
        } else {
            label = value + " ohms";
        }
        return label;
    }

    private int colorValue(String color) {
        for (int i = 0; i < COLORS.length; i++) {
            if (COLORS[i].equals(color)) {
                return i;
            }
        }
        throw new IllegalArgumentException("Invalid color: " + color);
    }
}
```

