import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import path from 'path';
import { fileURLToPath } from 'url';

function countLetters(text) {
  const freq = {};
  for (const char of text.toLowerCase()) {
    if (char >= 'a' && char <= 'z') {
      freq[char] = (freq[char] || 0) + 1;
    }
  }
  return freq;
}

function mergeFrequencies(freqs) {
  const result = {};
  for (const freq of freqs) {
    for (const [char, count] of Object.entries(freq)) {
      result[char] = (result[char] || 0) + count;
    }
  }
  return result;
}

if (!isMainThread) {
  // Worker thread: count letters and send result back
  const freq = countLetters(workerData);
  parentPort.postMessage(freq);
}

export const parallelLetterFrequency = async (texts) => {
  if (!isMainThread) {
    // Should never be called from worker
    throw new Error('parallelLetterFrequency should only be called from the main thread');
  }

  // Get the current file path in CommonJS style for Worker
  const __filename = fileURLToPath(import.meta.url);

  // For each text, spawn a worker to count letters
  const promises = texts.map(
    (text) =>
      new Promise((resolve, reject) => {
        const worker = new Worker(__filename, {
          workerData: text,
        });
        worker.on('message', resolve);
        worker.on('error', reject);
        worker.on('exit', (code) => {
          if (code !== 0)
            reject(new Error(`Worker stopped with exit code ${code}`));
        });
      })
  );

  const freqs = await Promise.all(promises);
  return mergeFrequencies(freqs);
};
