package kindergarten

import (
	"errors"
	"sort"
	"strings"
)

// Garden represents the kindergarten garden.
type Garden struct {
	children []string
	plants   map[string][]string
}

// plantMap maps diagram characters to plant names.
var plantMap = map[rune]string{
	'V': "violets",
	'R': "radishes",
	'C': "clover",
	'G': "grass",
}

// defaultChildren is the default list of children in alphabetical order.
var defaultChildren = []string{
	"Alice", "Bob", "Charlie", "David", "Eve", "Fred",
	"Ginny", "Harriet", "Ileana", "Joseph", "Kincaid", "Larry",
}

// NewGarden creates a new Garden from a diagram and a list of children.
func NewGarden(diagram string, children []string) (*Garden, error) {
	// Remove leading newline if present
	diagram = strings.TrimPrefix(diagram, "\n")
	rows := strings.Split(diagram, "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}

	row1 := rows[0]
	row2 := rows[1]

	// If children is empty, use default children
	if len(children) == 0 {
		children = defaultChildren
	} else {
		// Make a copy and sort alphabetically
		children = append([]string{}, children...)
		sort.Strings(children)
	}

	numChildren := len(children)
	if len(row1) != numChildren*2 || len(row2) != numChildren*2 {
		return nil, errors.New("diagram rows do not match number of children")
	}

	plants := make(map[string][]string, numChildren)
	for i, child := range children {
		indices := []int{2 * i, 2*i + 1}
		childPlants := make([]string, 0, 4)
		for _, idx := range indices {
			if plant, ok := plantMap[rune(row1[idx])]; ok {
				childPlants = append(childPlants, plant)
			} else {
				return nil, errors.New("invalid plant code in diagram")
			}
		}
		for _, idx := range indices {
			if plant, ok := plantMap[rune(row2[idx])]; ok {
				childPlants = append(childPlants, plant)
			} else {
				return nil, errors.New("invalid plant code in diagram")
			}
		}
		plants[child] = childPlants
	}

	return &Garden{
		children: children,
		plants:   plants,
	}, nil
}

// Plants returns the list of plants for a given child.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}
