package twobucket

import (
	"errors"
	"fmt"
)

// state represents the current state of the two buckets.
type state struct {
	b1, b2 int // current amount in bucket one and two
	steps  int // number of steps taken to reach this state
}

// Solve determines the minimum number of actions to reach the goal amount in one of the buckets.
func Solve(sizeBucketOne, sizeBucketTwo, goalAmount int, startBucket string) (goalBucket string, numSteps, otherBucketLevel int, e error) {
	// Validate input
	if sizeBucketOne <= 0 || sizeBucketTwo <= 0 || goalAmount <= 0 {
		return "", 0, 0, errors.New("bucket sizes and goal must be positive")
	}
	if startBucket != "one" && startBucket != "two" {
		return "", 0, 0, errors.New("startBucket must be 'one' or 'two'")
	}
	if goalAmount > sizeBucketOne && goalAmount > sizeBucketTwo {
		return "", 0, 0, errors.New("goal cannot be larger than both buckets")
	}
	if goalAmount != sizeBucketOne && goalAmount != sizeBucketTwo && goalAmount > max(sizeBucketOne, sizeBucketTwo) {
		return "", 0, 0, errors.New("goal cannot be larger than both buckets")
	}

	// Try both strategies: start with bucket one or bucket two
	if startBucket == "one" {
		return run(sizeBucketOne, sizeBucketTwo, goalAmount, true)
	} else {
		return run(sizeBucketOne, sizeBucketTwo, goalAmount, false)
	}
}

// run simulates the process, starting with the specified bucket.
func run(size1, size2, goal int, startWithOne bool) (goalBucket string, numSteps, otherBucketLevel int, e error) {
	visited := make(map[string]bool)
	var (
		b1, b2 int
		steps  int
	)
	if startWithOne {
		b1 = size1
		b2 = 0
	} else {
		b1 = 0
		b2 = size2
	}
	steps = 1

	for {
		// Check for goal
		if b1 == goal {
			return "one", steps, b2, nil
		}
		if b2 == goal {
			return "two", steps, b1, nil
		}

		// Mark state as visited
		key := fmt.Sprintf("%d,%d", b1, b2)
		if visited[key] {
			break // No solution found (cycle)
		}
		visited[key] = true

		// Decide next action
		if startWithOne {
			// Try to pour from bucket one to bucket two
			if b1 > 0 && b2 < size2 {
				transfer := min(b1, size2-b2)
				b1 -= transfer
				b2 += transfer
			} else if b1 == 0 {
				// Fill bucket one
				b1 = size1
			} else if b2 == size2 {
				// Empty bucket two
				b2 = 0
			}
		} else {
			// Try to pour from bucket two to bucket one
			if b2 > 0 && b1 < size1 {
				transfer := min(b2, size1-b1)
				b2 -= transfer
				b1 += transfer
			} else if b2 == 0 {
				// Fill bucket two
				b2 = size2
			} else if b1 == size1 {
				// Empty bucket one
				b1 = 0
			}
		}
		steps++
	}
	return "", 0, 0, errors.New("no solution found")
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
```

