package pov

type Tree struct {
	value    string
	children []*Tree
}

// New creates and returns a new Tree with the given root value and children.
func New(value string, children ...*Tree) *Tree {
	return &Tree{
		value:    value,
		children: children,
	}
}

// Value returns the value at the root of a tree.
func (tr *Tree) Value() string {
	return tr.value
}

// Children returns a slice containing the children of a tree.
// There is no need to sort the elements in the result slice,
// they can be in any order.
func (tr *Tree) Children() []*Tree {
	return tr.children
}

// String describes a tree in a compact S-expression format.
// This helps to make test outputs more readable.
// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// findPath finds the path from the current node to the node with the given value.
// It returns the path as a slice of *Tree, or nil if not found.
func (tr *Tree) findPath(value string) []*Tree {
	if tr == nil {
		return nil
	}
	if tr.value == value {
		return []*Tree{tr}
	}
	for _, child := range tr.children {
		if path := child.findPath(value); path != nil {
			return append([]*Tree{tr}, path...)
		}
	}
	return nil
}

// cloneExceptParent clones the tree, but does not include the parent in the children list.
func (tr *Tree) cloneExceptParent(parent *Tree) *Tree {
	if tr == nil {
		return nil
	}
	var newChildren []*Tree
	for _, child := range tr.children {
		if child != parent {
			newChildren = append(newChildren, child.cloneExceptParent(tr))
		}
	}
	return &Tree{
		value:    tr.value,
		children: newChildren,
	}
}

// FromPov returns the pov from the node specified in the argument.
func (tr *Tree) FromPov(from string) *Tree {
	path := tr.findPath(from)
	if path == nil {
		return nil
	}
	// Re-root the tree at the node with value "from"
	var newRoot *Tree
	var parent *Tree
	for i := len(path) - 1; i >= 0; i-- {
		node := path[i]
		// Clone the node, but exclude the parent from its children
		cloned := node.cloneExceptParent(parent)
		if newRoot != nil {
			cloned.children = append(cloned.children, newRoot)
		}
		newRoot = cloned
		parent = node
	}
	return newRoot
}

// findPathValues finds the path from the current node to the node with the given value.
// It returns the path as a slice of strings, or nil if not found.
func (tr *Tree) findPathValues(value string) []string {
	if tr == nil {
		return nil
	}
	if tr.value == value {
		return []string{tr.value}
	}
	for _, child := range tr.children {
		if path := child.findPathValues(value); path != nil {
			return append([]string{tr.value}, path...)
		}
	}
	return nil
}

// PathTo returns the shortest path between two nodes in the tree.
func (tr *Tree) PathTo(from, to string) []string {
	// Re-root the tree at "from"
	newRoot := tr.FromPov(from)
	if newRoot == nil {
		return nil
	}
	return newRoot.findPathValues(to)
}
```

