#include "binary_search_tree.h"

namespace binary_search_tree {

Node::Node(int value) : data(value), left(nullptr), right(nullptr) {}

BinarySearchTree::BinarySearchTree() : root(nullptr) {}

void BinarySearchTree::insert(int value) {
    insert_helper(root, value);
}

void BinarySearchTree::insert_helper(std::unique_ptr<Node>& node, int value) {
    if (!node) {
        node = std::make_unique<Node>(value);
    } else if (value <= node->data) {
        insert_helper(node->left, value);
    } else {
        insert_helper(node->right, value);
    }
}

bool BinarySearchTree::search(int value) const {
    return search_helper(root.get(), value);
}

bool BinarySearchTree::search_helper(const Node* node, int value) const {
    if (!node) {
        return false;
    }
    if (node->data == value) {
        return true;
    } else if (value < node->data) {
        return search_helper(node->left.get(), value);
    } else {
        return search_helper(node->right.get(), value);
    }
}

}  // namespace binary_search_tree
