/**
 * Converts a callback-based function to a function that returns a Promise.
 * The callback is expected to have the signature (error, ...results).
 * @param {Function} fn - The function to promisify.
 * @returns {Function} - A function that returns a Promise.
 */
export const promisify = (fn) => {
  return function (...args) {
    return new Promise((resolve, reject) => {
      fn(...args, (error, ...results) => {
        if (error) {
          reject(error);
        } else {
          // If only one result, resolve with it, else with array of results
          resolve(results.length > 1 ? results : results[0]);
        }
      });
    });
  };
};

/**
 * Returns a promise that resolves when all input promises resolve,
 * or rejects as soon as one rejects.
 * @param {Array<Promise>} promises
 * @returns {Promise}
 */
export const all = (promises) => {
  // Handle undefined or no arguments
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }
  if (!Array.isArray(promises)) {
    throw new TypeError('Argument must be an array');
  }
  return new Promise((resolve, reject) => {
    if (promises.length === 0) {
      resolve([]);
      return;
    }
    let results = [];
    let resolvedCount = 0;
    promises.forEach((p, i) => {
      Promise.resolve(p).then(
        (value) => {
          results[i] = value;
          resolvedCount++;
          if (resolvedCount === promises.length) {
            resolve(results);
          }
        },
        (err) => {
          reject(err);
        }
      );
    });
  });
};

