yacht.cpp
```
#include "yacht.h"
#include <algorithm>
#include <numeric>
#include <map>

namespace yacht {

int score(const std::vector<int>& dice, Category category) {
    std::map<int, int> counts;
    for (int d : dice) {
        counts[d]++;
    }

    switch (category) {
        case Category::Ones:
        case Category::Twos:
        case Category::Threes:
        case Category::Fours:
        case Category::Fives:
        case Category::Sixes: {
            int face = static_cast<int>(category) + 1;
            return face * counts[face];
        }
        case Category::FullHouse: {
            if (counts.size() == 2) {
                auto it = counts.begin();
                int first = it->second;
                int second = (++it)->second;
                if ((first == 3 && second == 2) || (first == 2 && second == 3)) {
                    return std::accumulate(dice.begin(), dice.end(), 0);
                }
            }
            return 0;
        }
        case Category::FourOfAKind: {
            for (const auto& kv : counts) {
                if (kv.second >= 4) {
                    return kv.first * 4;
                }
            }
            return 0;
        }
        case Category::LittleStraight: {
            static const std::vector<int> little = {1,2,3,4,5};
            std::vector<int> sorted = dice;
            std::sort(sorted.begin(), sorted.end());
            if (sorted == little) {
                return 30;
            }
            return 0;
        }
        case Category::BigStraight: {
            static const std::vector<int> big = {2,3,4,5,6};
            std::vector<int> sorted = dice;
            std::sort(sorted.begin(), sorted.end());
            if (sorted == big) {
                return 30;
            }
            return 0;
        }
        case Category::Choice: {
            return std::accumulate(dice.begin(), dice.end(), 0);
        }
        case Category::Yacht: {
            if (counts.size() == 1) {
                return 50;
            }
            return 0;
        }
        default:
            return 0;
    }
}

}  // namespace yacht
