import io.reactivex.Observable;
import io.reactivex.ObservableEmitter;
import io.reactivex.ObservableOnSubscribe;
import io.reactivex.functions.BiFunction;
import io.reactivex.functions.Function;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Set;

class Hangman {

    private static final int MAX_MISSES = Part.values().length;

    Observable<Output> play(Observable<String> words, Observable<String> letters) {
        // For each new word, start a new game
        return words.switchMap(secretWord -> {
            // Use scan to accumulate guesses and misses
            return letters
                .map(String::toLowerCase)
                .distinct()
                .scan(
                    new GameState(secretWord),
                    (state, letter) -> state.guess(letter)
                )
                .map(GameState::toOutput)
                .takeUntil(output -> output.status == Status.LOSE || output.status == Status.WIN);
        });
    }

    // Helper class to keep track of the game state
    private static class GameState {
        final String secret;
        final Set<String> guesses;
        final Set<String> misses;

        GameState(String secret) {
            this.secret = secret;
            this.guesses = new HashSet<>();
            this.misses = new HashSet<>();
        }

        GameState(String secret, Set<String> guesses, Set<String> misses) {
            this.secret = secret;
            this.guesses = guesses;
            this.misses = misses;
        }

        GameState guess(String letter) {
            Set<String> newGuesses = new HashSet<>(guesses);
            Set<String> newMisses = new HashSet<>(misses);
            if (!newGuesses.contains(letter)) {
                newGuesses.add(letter);
                if (!secret.toLowerCase().contains(letter)) {
                    newMisses.add(letter);
                }
            }
            return new GameState(secret, newGuesses, newMisses);
        }

        Output toOutput() {
            StringBuilder discovered = new StringBuilder();
            boolean allDiscovered = true;
            for (char c : secret.toCharArray()) {
                String s = String.valueOf(Character.toLowerCase(c));
                if (guesses.contains(s)) {
                    discovered.append(c);
                } else {
                    discovered.append('_');
                    allDiscovered = false;
                }
            }
            int missesCount = misses.size();
            List<Part> parts = new LinkedList<>();
            Part[] allParts = Part.values();
            for (int i = 0; i < missesCount && i < allParts.length; i++) {
                parts.add(allParts[i]);
            }
            Status status;
            if (allDiscovered) {
                status = Status.WIN;
            } else if (missesCount >= MAX_MISSES) {
                status = Status.LOSE;
            } else {
                status = Status.PLAYING;
            }
            return new Output(
                secret,
                discovered.toString(),
                guesses,
                misses,
                parts,
                status
            );
        }
    }
}
