package dominoes

type Domino [2]int

// MakeChain attempts to arrange the input dominoes into a legal chain.
// Returns the chain and true if possible, or nil and false if not.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	if n == 0 {
		return []Domino{}, true
	}
	if n == 1 {
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	used := make([]bool, n)
	chain := make([]Domino, 0, n)

	// Try every domino as a starting point, in both orientations
	for i := 0; i < n; i++ {
		for flip := 0; flip < 2; flip++ {
			start := input[i]
			if flip == 1 {
				start = Domino{input[i][1], input[i][0]}
			}
			used[i] = true
			chain = append(chain, start)
			if backtrack(input, used, chain, start[1], n) {
				return append([]Domino(nil), chain...), true
			}
			chain = chain[:0]
			used[i] = false
		}
	}
	return nil, false
}

// backtrack tries to build a chain recursively.
// chain: current chain
// want: the value to match on the next domino's left side
// n: total number of dominoes
func backtrack(input []Domino, used []bool, chain []Domino, want int, n int) bool {
	if len(chain) == n {
		// Check if the chain is closed (first and last match)
		return chain[0][0] == chain[len(chain)-1][1]
	}
	for i := 0; i < n; i++ {
		if used[i] {
			continue
		}
		for flip := 0; flip < 2; flip++ {
			d := input[i]
			if flip == 1 {
				d = Domino{input[i][1], input[i][0]}
			}
			if d[0] == want {
				used[i] = true
				chain = append(chain, d)
				if backtrack(input, used, chain, d[1], n) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
	}
	return false
}
