import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class KindergartenGarden {

    private static final List<String> STUDENTS = Arrays.asList(
        "Alice", "Bob", "Charlie", "David", "Eve", "Fred",
        "Ginny", "Harriet", "Ileana", "Joseph", "Kincaid", "Larry"
    );

    private static final Map<Character, Plant> PLANT_MAP = new HashMap<>();
    static {
        PLANT_MAP.put('G', Plant.GRASS);
        PLANT_MAP.put('C', Plant.CLOVER);
        PLANT_MAP.put('R', Plant.RADISHES);
        PLANT_MAP.put('V', Plant.VIOLETS);
    }

    private final String[] rows;

    KindergartenGarden(String garden) {
        // Split the garden string into two rows
        this.rows = garden.split("\n");
        if (rows.length != 2) {
            throw new IllegalArgumentException("Garden diagram must have exactly two rows.");
        }
        if (rows[0].length() != rows[1].length()) {
            throw new IllegalArgumentException("Both rows must have the same number of cups.");
        }
    }

    List<Plant> getPlantsOfStudent(String student) {
        int studentIndex = STUDENTS.indexOf(student);
        if (studentIndex == -1) {
            throw new IllegalArgumentException("Unknown student: " + student);
        }
        List<Plant> plants = new ArrayList<>(4);
        // Each student gets 2 cups per row, so calculate the starting index
        int start = studentIndex * 2;
        for (int row = 0; row < 2; row++) {
            plants.add(PLANT_MAP.get(rows[row].charAt(start)));
            plants.add(PLANT_MAP.get(rows[row].charAt(start + 1)));
        }
        return plants;
    }
}
