#!/usr/bin/env node

// The above line is a shebang. On Unix-like operating systems, or environments,
// this will allow the script to be run by node, and thus turn this JavaScript
// file into an executable. In other words, to execute this file, you may run
// the following from your terminal:
//
// ./grep.js args
//
// If you don't have a Unix-like operating system or environment, for example
// Windows without WSL, you can use the following inside a window terminal,
// such as cmd.exe:
//
// node grep.js args
//
// Read more about shebangs here: https://en.wikipedia.org/wiki/Shebang_(Unix)

const fs = require('fs');
const path = require('path');

/**
 * Reads the given file and returns lines.
 *
 * This function works regardless of POSIX (LF) or windows (CRLF) encoding.
 *
 * @param {string} file path to file
 * @returns {string[]} the lines
 */
function readLines(file) {
  const data = fs.readFileSync(path.resolve(file), { encoding: 'utf-8' });
  return data.split(/\r?\n/);
}

const VALID_OPTIONS = [
  'n', // add line numbers
  'l', // print file names where pattern is found
  'i', // ignore case
  'v', // reverse files results
  'x', // match entire line
];

const ARGS = process.argv;

// --- Argument parsing ---

// ARGS[0] = node, ARGS[1] = script, ARGS[2] = search string, ARGS[3...] = flags/files
if (ARGS.length < 4) {
  console.error('Usage: grep.js <search string> [flags] <file>...');
  process.exit(1);
}

const searchString = ARGS[2];
const flags = [];
const files = [];

for (let i = 3; i < ARGS.length; i++) {
  const arg = ARGS[i];
  if (arg.startsWith('-')) {
    // collect all single-letter flags, e.g. -in
    for (let j = 1; j < arg.length; j++) {
      if (VALID_OPTIONS.includes(arg[j])) {
        if (!flags.includes(arg[j])) {
          flags.push(arg[j]);
        }
      } else {
        console.error(`Invalid flag: -${arg[j]}`);
        process.exit(1);
      }
    }
  } else {
    files.push(arg);
  }
}

if (files.length === 0) {
  console.error('No files specified.');
  process.exit(1);
}

const showLineNumbers = flags.includes('n');
const showFileNamesOnly = flags.includes('l');
const ignoreCase = flags.includes('i');
const invertMatch = flags.includes('v');
const matchEntireLine = flags.includes('x');

function matchLine(line, searchString) {
  let lineToCheck = line;
  let search = searchString;
  if (ignoreCase) {
    lineToCheck = lineToCheck.toLowerCase();
    search = search.toLowerCase();
  }
  if (matchEntireLine) {
    return lineToCheck === search;
  } else {
    return lineToCheck.includes(search);
  }
}

let output = [];
let filesWithMatch = new Set();

for (const file of files) {
  let lines;
  try {
    lines = readLines(file);
  } catch (e) {
    console.error(`Error reading file: ${file}`);
    process.exit(1);
  }
  let fileMatched = false;
  for (let idx = 0; idx < lines.length; idx++) {
    const line = lines[idx];
    const isMatch = matchLine(line, searchString);
    const finalMatch = invertMatch ? !isMatch : isMatch;
    if (finalMatch) {
      fileMatched = true;
      if (!showFileNamesOnly) {
        let outLine = '';
        if (files.length > 1) {
          outLine += `${file}:`;
        }
        if (showLineNumbers) {
          outLine += `${idx + 1}:`;
        }
        outLine += line;
        output.push(outLine);
      }
    }
  }
  if (fileMatched && showFileNamesOnly) {
    filesWithMatch.add(file);
  }
}

if (showFileNamesOnly) {
  for (const file of files) {
    if (filesWithMatch.has(file)) {
      console.log(file);
    }
  }
} else {
  for (const line of output) {
    console.log(line);
  }
}
