```
package react

type (
	Reactor interface {
		CreateInput(initial int) InputCell
		CreateCompute1(dep Cell, compute func(int) int) ComputeCell
		CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell
	}

	Cell interface {
		Value() int
	}

	InputCell interface {
		Cell
		SetValue(value int)
	}

	ComputeCell interface {
		Cell
		AddCallback(func(int)) Canceler
	}

	Canceler interface {
		Cancel()
	}
)

type reactor struct {
	// We keep a list of all cells for propagation
	cells []*cell
}

type cell struct {
	value      int
	isInput    bool
	compute1   func(int) int
	compute2   func(int, int) int
	deps       []*cell
	callbacks  map[int]func(int)
	nextCbID   int
	reactor    *reactor
}

type canceler struct {
	cell    *cell
	cbID    int
	canceled bool
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{
		value:     initial,
		isInput:   true,
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	depCell := dep.(*cell)
	c := &cell{
		isInput:   false,
		compute1:  compute,
		deps:      []*cell{depCell},
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
	c.value = compute(depCell.Value())
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	depCell1 := dep1.(*cell)
	depCell2 := dep2.(*cell)
	c := &cell{
		isInput:   false,
		compute2:  compute,
		deps:      []*cell{depCell1, depCell2},
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
	c.value = compute(depCell1.Value(), depCell2.Value())
	r.cells = append(r.cells, c)
	return c
}

func (c *cell) Value() int {
	return c.value
}

func (c *cell) SetValue(value int) {
	if !c.isInput {
		return
	}
	if c.value == value {
		return
	}
	c.value = value
	c.reactor.propagate()
}

func (c *cell) AddCallback(callback func(int)) Canceler {
	c.nextCbID++
	cbID := c.nextCbID
	c.callbacks[cbID] = callback
	return &canceler{cell: c, cbID: cbID}
}

func (c *canceler) Cancel() {
	if c.canceled {
		return
	}
	delete(c.cell.callbacks, c.cbID)
	c.canceled = true
}

// propagate recalculates all compute cells in dependency order and fires callbacks if values changed.
func (r *reactor) propagate() {
	// To avoid recomputing cells multiple times, we do a simple topological sort.
	// For this small system, we just iterate until stable.
	changed := true
	// Track previous values for callback firing
	prevValues := make(map[*cell]int)
	for _, c := range r.cells {
		prevValues[c] = c.value
	}
	for changed {
		changed = false
		for _, c := range r.cells {
			if c.isInput {
				continue
			}
			old := c.value
			if c.compute1 != nil && len(c.deps) == 1 {
				c.value = c.compute1(c.deps[0].Value())
			} else if c.compute2 != nil && len(c.deps) == 2 {
				c.value = c.compute2(c.deps[0].Value(), c.deps[1].Value())
			}
			if c.value != old {
				changed = true
			}
		}
	}
	// Fire callbacks for compute cells whose value changed
	for _, c := range r.cells {
		if c.isInput {
			continue
		}
		if c.value != prevValues[c] {
			for _, cb := range c.callbacks {
				cb(c.value)
			}
		}
	}
}
