import java.awt.Point;
import java.util.*;

enum Player {
    BLACK, WHITE, NONE
}

class GoCounting {

    private final char[][] board;
    private final int rows;
    private final int cols;

    GoCounting(String boardString) {
        String[] lines = boardString.split("\n");
        rows = lines.length;
        cols = lines[0].length();
        board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            board[i] = lines[i].toCharArray();
        }
    }

    Player getTerritoryOwner(int x, int y) {
        Set<Point> territory = getTerritory(x, y);
        if (territory.isEmpty()) {
            return Player.NONE;
        }
        Set<Character> bordering = borderingStones(territory);
        if (bordering.size() == 1) {
            char c = bordering.iterator().next();
            if (c == 'B') return Player.BLACK;
            if (c == 'W') return Player.WHITE;
        }
        return Player.NONE;
    }

    Set<Point> getTerritory(int x, int y) {
        if (!inBounds(x, y) || board[y][x] == 'B' || board[y][x] == 'W') {
            return Collections.emptySet();
        }
        Set<Point> territory = new HashSet<>();
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(x, y));
        visited[y][x] = true;

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            territory.add(p);
            for (Point n : neighbors(p)) {
                if (!visited[n.y][n.x] && board[n.y][n.x] == ' ') {
                    visited[n.y][n.x] = true;
                    queue.add(n);
                }
            }
        }
        return territory;
    }

    Map<Player, Set<Point>> getTerritories() {
        Map<Player, Set<Point>> result = new EnumMap<>(Player.class);
        result.put(Player.BLACK, new HashSet<>());
        result.put(Player.WHITE, new HashSet<>());
        result.put(Player.NONE, new HashSet<>());
        boolean[][] visited = new boolean[rows][cols];

        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                if (board[y][x] == ' ' && !visited[y][x]) {
                    Set<Point> terr = getTerritory(x, y);
                    Player owner = Player.NONE;
                    if (!terr.isEmpty()) {
                        owner = getTerritoryOwner(x, y);
                        for (Point p : terr) {
                            visited[p.y][p.x] = true;
                        }
                        result.get(owner).addAll(terr);
                    }
                }
            }
        }
        return result;
    }

    private boolean inBounds(int x, int y) {
        return y >= 0 && y < rows && x >= 0 && x < cols;
    }

    private List<Point> neighbors(Point p) {
        int[][] dirs = {{0,1},{1,0},{0,-1},{-1,0}};
        List<Point> result = new ArrayList<>();
        for (int[] d : dirs) {
            int nx = p.x + d[0];
            int ny = p.y + d[1];
            if (inBounds(nx, ny)) {
                result.add(new Point(nx, ny));
            }
        }
        return result;
    }

    private Set<Character> borderingStones(Set<Point> territory) {
        Set<Character> bordering = new HashSet<>();
        for (Point p : territory) {
            for (Point n : neighbors(p)) {
                char c = board[n.y][n.x];
                if (c == 'B' || c == 'W') {
                    bordering.add(c);
                }
            }
        }
        return bordering;
    }
